dEvent="Loaded"><BeginStoryboard><Storyboard RepeatBehavior="Forever" AutoReverse="True"><DoubleAnimation Storyboard.TargetProperty="Opacity" From="1" To="0.05" Duration="0:0:0.35"/></Storyboard></BeginStoryboard></EventTrigger></Ellipse.Triggers></Ellipse><Ellipse Width="28" Height="28" Fill="#1E90FF" Stroke="White" StrokeThickness="3" Margin="0" VerticalAlignment="Center"><Ellipse.Effect><DropShadowEffect ShadowDepth="0" BlurRadius="20" Opacity="0.9" Color="#1E90FF"/></Ellipse.Effect><Ellipse.Triggers><EventTrigger RoutedEvent="Loaded"><BeginStoryboard><Storyboard RepeatBehavior="Forever" AutoReverse="True"><DoubleAnimation Storyboard.TargetProperty="Opacity" From="0.05" To="1" Duration="0:0:0.35"/></Storyboard></BeginStoryboard></EventTrigger></Ellipse.Triggers></Ellipse><StackPanel VerticalAlignment="Center" Margin="16,0,0,0"><TextBlock x:Name="DiskWarningTitle" FontSize="20" FontWeight="ExtraBold" Foreground="#B42318"/></StackPanel><TextBlock x:Name="DiskWarningMore" Text="More info - click here" FontSize="16" FontWeight="SemiBold" Foreground="#1E5BD8" TextDecorations="Underline" Cursor="Hand" VerticalAlignment="Center" Margin="22,0,0,0"/></StackPanel></Border></StackPanel><Border x:Name="ProtectedPill" Grid.Column="1" CornerRadius="16" Background="#E7F6EF" Padding="12,7" VerticalAlignment="Center"><TextBlock Text="●  Protected mode" Foreground="{StaticResource Success}" FontSize="12"/></Border></Grid>

            <Grid Grid.Row="1">
                <ScrollViewer x:Name="PageDashboard" VerticalScrollBarVisibility="Auto"><StackPanel>
<Border x:Name="UpdateBanner" Visibility="Collapsed" Background="#12C25B" CornerRadius="12" Padding="20,14" Margin="0,0,0,16"><Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel Orientation="Horizontal" VerticalAlignment="Center"><TextBlock Text="&#10004;" Foreground="White" FontSize="22" FontWeight="Bold" VerticalAlignment="Center" Margin="0,0,12,0"/><TextBlock x:Name="UpdateBannerText" Text="There is a new update" Foreground="White" FontSize="18" FontWeight="Bold" VerticalAlignment="Center" TextWrapping="Wrap"/></StackPanel><Button x:Name="UpdateBannerButton" Grid.Column="1" Content="See what is new and update" Style="{StaticResource HeroButton}" Foreground="#0B7A3B" Margin="16,0,0,0"/></Grid></Border>
<Border Style="{StaticResource Card}" Effect="{DynamicResource DR3DShadow}" Padding="34" Margin="0,0,0,18" Background="{StaticResource HeroBrush}" BorderBrush="#2447B8"><Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><Border Grid.RowSpan="2" Margin="-34" CornerRadius="14" IsHitTestVisible="False" Visibility="{DynamicResource DR3DParts}" BorderThickness="3,3,3,9" BorderBrush="#99FFFFFF"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#66FFFFFF" Offset="0"/><GradientStop Color="#14FFFFFF" Offset="0.30"/><GradientStop Color="#00000000" Offset="0.55"/><GradientStop Color="#99000820" Offset="1"/></LinearGradientBrush></Border.Background></Border><Grid Grid.Row="0" Panel.ZIndex="5" HorizontalAlignment="Center" VerticalAlignment="Top" Margin="0,-14,0,0"><Button x:Name="EstimateTimeButton" Style="{StaticResource HeroGreenButton}" Height="62" MinWidth="520" Cursor="Hand" ToolTip="Shows about how long a Safe, Medium and Advanced scan would take on this PC"><Button.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#FFF27A" Offset="0"/><GradientStop Color="#F5B400" Offset="1"/></LinearGradientBrush></Button.Background></Button><StackPanel IsHitTestVisible="False" HorizontalAlignment="Center" VerticalAlignment="Center" Margin="0,0,0,6"><TextBlock Text="&#x23F1; Check here first!  Every time, to see how long it takes" Foreground="#2B1A00" FontSize="15" FontWeight="ExtraBold" HorizontalAlignment="Center"/><TextBlock Text="to clean up your PC  &#x2192;  3 Choices." Foreground="#2B1A00" FontSize="13" Margin="0,2,0,0" FontWeight="SemiBold" HorizontalAlignment="Center"/></StackPanel></Grid><Button x:Name="LangButton" Grid.Row="0" Panel.ZIndex="6" HorizontalAlignment="Right" VerticalAlignment="Top" Margin="0,58,-12,0" Style="{StaticResource HeroGreenButton}" Padding="16,8" Cursor="Hand" ToolTip="Français / English"><Button.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#4DB8FF" Offset="0"/><GradientStop Color="#0A5FD0" Offset="1"/></LinearGradientBrush></Button.Background><StackPanel Orientation="Horizontal"><TextBlock Text="&#x1F310;" FontFamily="Segoe UI Emoji" FontSize="15" Foreground="White" VerticalAlignment="Center" Margin="0,0,7,0"/><TextBlock x:Name="LangButtonText" Text="Fran&#xE7;ais" Foreground="White" FontWeight="Bold" FontSize="14" VerticalAlignment="Center"/></StackPanel></Button><StackPanel HorizontalAlignment="Center" Margin="0,56,0,0"><StackPanel x:Name="StartHereRow" Orientation="Horizontal" HorizontalAlignment="Center" Background="Transparent" Cursor="Hand" ToolTip="Click to see how long each scan takes on this PC"><StackPanel.RenderTransform><TranslateTransform/></StackPanel.RenderTransform><StackPanel.Triggers><EventTrigger RoutedEvent="Loaded"><BeginStoryboard><Storyboard RepeatBehavior="Forever"><DoubleAnimationUsingKeyFrames Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.Y)"><EasingDoubleKeyFrame KeyTime="0:0:0" Value="0"/><EasingDoubleKeyFrame KeyTime="0:0:0.35" Value="-7"><EasingDoubleKeyFrame.EasingFunction><QuadraticEase EasingMode="EaseOut"/></EasingDoubleKeyFrame.EasingFunction></EasingDoubleKeyFrame><EasingDoubleKeyFrame KeyTime="0:0:0.8" Value="0"><EasingDoubleKeyFrame.EasingFunction><BounceEase Bounces="2" Bounciness="3" EasingMode="EaseOut"/></EasingDoubleKeyFrame.EasingFunction></EasingDoubleKeyFrame><EasingDoubleKeyFrame KeyTime="0:0:1.6" Value="0"/></DoubleAnimationUsingKeyFrames></Storyboard></BeginStoryboard></EventTrigger></StackPanel.Triggers><TextBlock Text="&#x25B2;" FontFamily="Segoe UI Symbol" Foreground="#19E36B" FontSize="24" FontWeight="ExtraBold" VerticalAlignment="Center" Margin="0,0,10,0"><TextBlock.Effect><DropShadowEffect Color="#003A12" ShadowDepth="2" BlurRadius="3"/></TextBlock.Effect></TextBlock><TextBlock Text="START HERE" Effect="{DynamicResource DR3DHeroText}" VerticalAlignment="Center" Foreground="#FFFF33" FontSize="12.5" FontWeight="ExtraBold"/><TextBlock Text="&#x25B2;" FontFamily="Segoe UI Symbol" Foreground="#19E36B" FontSize="24" FontWeight="ExtraBold" VerticalAlignment="Center" Margin="10,0,0,0"><TextBlock.Effect><DropShadowEffect Color="#003A12" ShadowDepth="2" BlurRadius="3"/></TextBlock.Effect></TextBlock></StackPanel><Grid HorizontalAlignment="Center" Margin="0,8,6,14"><TextBlock Text="Make my PC cleaner" Foreground="#0A1D78" FontSize="32" FontWeight="ExtraBold" IsHitTestVisible="False" Visibility="{DynamicResource DR3DParts}"><TextBlock.RenderTransform><TranslateTransform X="6" Y="6"/></TextBlock.RenderTransform><TextBlock.Effect><BlurEffect Radius="4"/></TextBlock.Effect></TextBlock><TextBlock Text="Make my PC cleaner" Foreground="#0A1D78" FontSize="32" FontWeight="ExtraBold" IsHitTestVisible="False" Visibility="{DynamicResource DR3DParts}"><TextBlock.RenderTransform><TranslateTransform X="4" Y="4"/></TextBlock.RenderTransform></TextBlock><TextBlock Text="Make my PC cleaner" Foreground="#1A35A8" FontSize="32" FontWeight="ExtraBold" IsHitTestVisible="False" Visibility="{DynamicResource DR3DParts}"><TextBlock.RenderTransform><TranslateTransform X="3" Y="3"/></TextBlock.RenderTransform></TextBlock><TextBlock Text="Make my PC cleaner" Foreground="#2447B8" FontSize="32" FontWeight="ExtraBold" IsHitTestVisible="False" Visibility="{DynamicResource DR3DParts}"><TextBlock.RenderTransform><TranslateTransform X="2" Y="2"/></TextBlock.RenderTransform></TextBlock><TextBlock Text="Make my PC cleaner" Foreground="#3A5FD0" FontSize="32" FontWeight="ExtraBold" IsHitTestVisible="False" Visibility="{DynamicResource DR3DParts}"><TextBlock.RenderTransform><TranslateTransform X="1" Y="1"/></TextBlock.RenderTransform></TextBlock><TextBlock Text="Make my PC cleaner" FontSize="32" FontWeight="ExtraBold"><TextBlock.Foreground><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#FFFFFF" Offset="0"/><GradientStop Color="#F4F8FF" Offset="0.48"/><GradientStop Color="#BFD4FF" Offset="0.52"/><GradientStop Color="#FFFFFF" Offset="1"/></LinearGradientBrush></TextBlock.Foreground></TextBlock></Grid><TextBlock Visibility="Collapsed" Text="One click. We only do the safe things, and we ask you before anything starts." Effect="{DynamicResource DR3DHeroText}" Foreground="#C9D9FF" FontSize="16" TextWrapping="Wrap" MaxWidth="560" HorizontalAlignment="Center" TextAlignment="Center"/><Grid Margin="0,24,0,0"><Button x:Name="HeroCloneButton" HorizontalAlignment="Left" VerticalAlignment="Center" Margin="0,0,0,10" Cursor="Hand" ToolTip="Open Clone &amp; Backup: SmartCopy, Secure, Restore and Rescue USB" Focusable="False"><Button.Template><ControlTemplate TargetType="Button"><Grid x:Name="HcRoot" Background="Transparent"><ContentPresenter/></Grid><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="HcRoot" Property="Opacity" Value="0.85"/></Trigger><Trigger Property="IsPressed" Value="True"><Setter TargetName="HcRoot" Property="Opacity" Value="0.7"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template><StackPanel><Viewbox x:Name="HeroCloneBox" Width="96" Height="96" IsHitTestVisible="False"><Canvas Width="64" Height="64"><Canvas.Effect><DropShadowEffect Color="#000000" Direction="300" ShadowDepth="3" BlurRadius="5" Opacity="0.6"/></Canvas.Effect><Canvas.Resources><LinearGradientBrush x:Key="CbBlueTop" StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#E3F2FF" Offset="0"/><GradientStop Color="#7DB8FF" Offset="1"/></LinearGradientBrush><LinearGradientBrush x:Key="CbBlueFront" StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#4F8CF0" Offset="0"/><GradientStop Color="#1F5FE0" Offset="0.5"/><GradientStop Color="#0B2F8A" Offset="1"/></LinearGradientBrush><LinearGradientBrush x:Key="CbGoldTop" StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#FFF8D0" Offset="0"/><GradientStop Color="#FFD24A" Offset="1"/></LinearGradientBrush><LinearGradientBrush x:Key="CbGoldFront" StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#FFC23A" Offset="0"/><GradientStop Color="#E08A00" Offset="0.55"/><GradientStop Color="#8A4A00" Offset="1"/></LinearGradientBrush><LinearGradientBrush x:Key="CbGreen" StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#B8FFC8" Offset="0"/><GradientStop Color="#2BD45A" Offset="0.45"/><GradientStop Color="#0B7A2C" Offset="1"/></LinearGradientBrush></Canvas.Resources><Path Fill="{StaticResource CbBlueTop}" Stroke="#0B2F8A" StrokeThickness="1" Data="M 4,30 L 12,24 L 36,24 L 28,30 Z"/><Path Fill="#123A9A" Stroke="#0B2F8A" StrokeThickness="1" Data="M 28,30 L 36,24 L 36,34 L 28,40 Z"/><Rectangle Canvas.Left="4" Canvas.Top="30" Width="24" Height="10" RadiusX="1.5" RadiusY="1.5" Fill="{StaticResource CbBlueFront}" Stroke="#0B2F8A" StrokeThickness="1"/><Ellipse Canvas.Left="22" Canvas.Top="33.5" Width="3.5" Height="3.5" Fill="#5CFF8A"/><Rectangle Canvas.Left="6" Canvas.Top="31" Width="20" Height="2.5" RadiusX="1" RadiusY="1" Fill="#66FFFFFF"/><Path Fill="{StaticResource CbGoldTop}" Stroke="#8A4A00" StrokeThickness="1" Data="M 26,46 L 34,40 L 60,40 L 52,46 Z"/><Path Fill="#A35A00" Stroke="#8A4A00" StrokeThickness="1" Data="M 52,46 L 60,40 L 60,50 L 52,56 Z"/><Rectangle Canvas.Left="26" Canvas.Top="46" Width="26" Height="10" RadiusX="1.5" RadiusY="1.5" Fill="{StaticResource CbGoldFront}" Stroke="#8A4A00" StrokeThickness="1"/><Ellipse Canvas.Left="46" Canvas.Top="49.5" Width="3.5" Height="3.5" Fill="#5CFF8A"/><Rectangle Canvas.Left="28" Canvas.Top="47" Width="22" Height="2.5" RadiusX="1" RadiusY="1" Fill="#77FFFFFF"/><Path Stroke="#0B5A20" StrokeThickness="7" StrokeStartLineCap="Round" Data="M 16,22 C 18,6 44,4 48,30"/><Path Stroke="{StaticResource CbGreen}" StrokeThickness="5" StrokeStartLineCap="Round" Data="M 16,22 C 18,6 44,4 48,30"/><Path Fill="{StaticResource CbGreen}" Stroke="#0B5A20" StrokeThickness="1.2" StrokeLineJoin="Round" Data="M 40,27 L 56,27 L 48,38 Z"/><Path Stroke="#CCFFFFFF" StrokeThickness="1.5" StrokeStartLineCap="Round" StrokeEndLineCap="Round" Data="M 19,17 C 23,9 36,8 42,15"/></Canvas></Viewbox><TextBlock Text="Clone &amp; Backup" HorizontalAlignment="Center" Margin="0,-10,0,0" Foreground="#FFFFFF" FontSize="15" FontWeight="ExtraBold" IsHitTestVisible="False"><TextBlock.Effect><DropShadowEffect Color="#000820" Direction="300" ShadowDepth="2" BlurRadius="3" Opacity="0.9"/></TextBlock.Effect></TextBlock></StackPanel></Button><WrapPanel Orientation="Horizontal" HorizontalAlignment="Center" VerticalAlignment="Center"><Button x:Name="SafeCleanButton" Content="Make my PC cleaner" VerticalAlignment="Center" Style="{StaticResource HeroGreenButton}" FontSize="15" FontWeight="Bold" Padding="20,9" Margin="0,0,10,10"><Button.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#5BE584" Offset="0"/><GradientStop Color="#13A64A" Offset="1"/></LinearGradientBrush></Button.Background></Button><Button x:Name="SafePreviewButton" Content="Show me first" Visibility="Collapsed" Style="{StaticResource HeroGreenButton}" Padding="18,9" Margin="0,0,10,10"><Button.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#0E5A2D" Offset="0"/><GradientStop Color="#02240F" Offset="1"/></LinearGradientBrush></Button.Background></Button><Button x:Name="HeroUninstallButton" Visibility="Collapsed" Style="{StaticResource HeroGreenButton}" Margin="0,0,10,10" ToolTip="Open the DRDirect Uninstaller Program to remove programs you no longer want"><StackPanel Orientation="Horizontal"><TextBlock Text="⌫" FontSize="14" Foreground="White" Margin="0,0,8,0" VerticalAlignment="Center"/><TextBlock Text="DRDirect Uninstaller Program" Foreground="White" FontWeight="SemiBold" VerticalAlignment="Center"/></StackPanel></Button></WrapPanel></Grid><TextBlock x:Name="HeroToolsHint" Cursor="Hand" Effect="{DynamicResource DR3DHeroText}" Foreground="#FFD54A" FontSize="17" FontWeight="Bold" Margin="0,6,0,0" TextWrapping="Wrap" HorizontalAlignment="Center" TextAlignment="Center"><Run Text="Uninstaller" Foreground="#4DB8FF"/><Run Text=" and "/><Run Text="Duplicate Finder" Foreground="#2BE37A"/><Run Text=" are both inside "/><Run Text="AND MORE!" Foreground="White"/><Run Text=" Press Show all tools."/></TextBlock><TextBlock Text="✓  Settings changes can be undone.   ✓  Files and passwords stay safe unless you tick them.&#x0A;Read each item first. DRDirect is not responsible for what you tick unread." Effect="{DynamicResource DR3DHeroText}" Foreground="White" FontSize="13.5" FontWeight="SemiBold" Margin="0,20,0,0" TextWrapping="Wrap" HorizontalAlignment="Center" TextAlignment="Center"/><Button x:Name="ReadmeIconButton" Style="{StaticResource HeroGreenButton}" Margin="0,8,0,0" HorizontalAlignment="Center" Padding="10,5" ToolTip="Read me: a short, friendly note"><Button.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#4DB8FF" Offset="0"/><GradientStop Color="#0A5FD0" Offset="1"/></LinearGradientBrush></Button.Background><StackPanel Orientation="Horizontal"><TextBlock Text="&#xE82D;" FontFamily="Segoe Fluent Icons, Segoe MDL2 Assets" FontSize="16" Foreground="White" VerticalAlignment="Center"/></StackPanel></Button></StackPanel><Grid Grid.Row="1"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel Grid.Column="0" Orientation="Horizontal" HorizontalAlignment="Left" VerticalAlignment="Center" Margin="0,10,12,0"><CheckBox x:Name="SoundSwitch" Style="{StaticResource DRSwitch}" Effect="{DynamicResource DR3DHeroText}" Content="Sound" Margin="0,0,14,0" VerticalAlignment="Center" ToolTip="Sounds: a soft chime when a clean finishes, and a small tick when you point at a button"/><CheckBox x:Name="Buttons3DSwitch" Style="{StaticResource DRSwitch}" Effect="{DynamicResource DR3DHeroText}" Content="3D look" Margin="0,0,14,0" VerticalAlignment="Center" ToolTip="Turn the raised 3D look of the Cleaner on or off"/><CheckBox x:Name="Max3DSwitch" Style="{StaticResource DRSwitch}" Effect="{DynamicResource DR3DHeroText}" Content="Max 3D" Margin="0,0,14,0" VerticalAlignment="Center" ToolTip="Even deeper 3D: bigger shadows and thicker raised edges. Turns the 3D look on too."/></StackPanel><Button x:Name="HeroUpdateButton" Content="Check for updates" Style="{StaticResource HeroGreenButton}" Grid.Column="1" Margin="0,10,0,0" HorizontalAlignment="Right" VerticalAlignment="Top" Padding="18,9" ToolTip="Look for a newer version of the Cleaner"><Button.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#D2700F" Offset="0"/><GradientStop Color="#8F3800" Offset="1"/></LinearGradientBrush></Button.Background></Button></Grid></Grid></Border>
<UniformGrid Columns="3" Margin="0,0,0,22">
                            <Border x:Name="LastCleanCard" Style="{StaticResource Card}" Margin="0,0,12,0" BorderBrush="{StaticResource Violet}" BorderThickness="5,1,1,1"><Grid><StackPanel><StackPanel Orientation="Horizontal"><Border Style="{StaticResource StatIcon}" Background="{StaticResource VioletSoft}"><TextBlock Text="◷" Foreground="{StaticResource Violet}" FontSize="19" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><TextBlock Text="LAST CLEAN" Foreground="{StaticResource Violet}" FontSize="11" FontWeight="Bold" VerticalAlignment="Center"/></StackPanel><TextBlock x:Name="LastCleanValue" Text="Not yet" FontSize="23" FontWeight="SemiBold" Margin="0,12,0,2"/><TextBlock x:Name="LastCleanHint" Text="Shows here after your first clean" Style="{StaticResource MutedText}" FontSize="12" TextWrapping="Wrap"/><Grid Margin="0,10,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><StackPanel Orientation="Horizontal" VerticalAlignment="Top" Margin="0,2,8,0"><Ellipse x:Name="QuickLightA" Width="12" Height="12" Margin="0,0,3,0" Visibility="Collapsed"/><Ellipse x:Name="QuickLightB" Width="12" Height="12" Visibility="Collapsed"/></StackPanel><TextBlock Grid.Column="1" x:Name="LastCleanQuickScan" Style="{StaticResource MutedText}" FontSize="12" TextWrapping="Wrap" Visibility="Collapsed"/></Grid><Grid Margin="0,4,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><StackPanel Orientation="Horizontal" VerticalAlignment="Top" Margin="0,2,8,0"><Ellipse x:Name="FullLightA" Width="12" Height="12" Margin="0,0,3,0" Visibility="Collapsed"/><Ellipse x:Name="FullLightB" Width="12" Height="12" Visibility="Collapsed"/></StackPanel><TextBlock Grid.Column="1" x:Name="LastCleanFullScan" Style="{StaticResource MutedText}" FontSize="12" TextWrapping="Wrap" Visibility="Collapsed"/></Grid></StackPanel><Ellipse x:Name="LastCleanLightBlue" Width="14" Height="14" Fill="#1E90FF" Margin="-12,-12,0,0" HorizontalAlignment="Left" VerticalAlignment="Top" Visibility="Collapsed"><Ellipse.Effect><DropShadowEffect Color="#1E90FF" BlurRadius="14" ShadowDepth="0" Opacity="0.9"/></Ellipse.Effect></Ellipse><Ellipse x:Name="LastCleanLightRed" Width="14" Height="14" Fill="#E02424" Margin="0,-12,-12,0" HorizontalAlignment="Right" VerticalAlignment="Top" Visibility="Collapsed"><Ellipse.Effect><DropShadowEffect Color="#E02424" BlurRadius="14" ShadowDepth="0" Opacity="0.9"/></Ellipse.Effect></Ellipse></Grid></Border>
                            <Border Style="{StaticResource Card}" Margin="0,0,12,0" BorderBrush="{StaticResource Teal}" BorderThickness="5,1,1,1"><StackPanel><StackPanel Orientation="Horizontal"><Border Style="{StaticResource StatIcon}" Background="{StaticResource TealSoft}"><TextBlock Text="▰" Foreground="{StaticResource Teal}" FontSize="17" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><TextBlock Text="FREE SPACE" Foreground="{StaticResource Teal}" FontSize="11" FontWeight="Bold" VerticalAlignment="Center"/></StackPanel><TextBlock x:Name="FreeSpaceText" Text="Checking…" FontSize="23" FontWeight="SemiBold" Margin="0,12,0,2"/><TextBlock Text="On your main drive" Style="{StaticResource MutedText}" FontSize="12"/></StackPanel></Border>
                            <Border x:Name="HealthCard" Style="{StaticResource Card}" BorderBrush="{StaticResource Amber}" BorderThickness="5,1,1,1"><StackPanel><StackPanel Orientation="Horizontal"><Border x:Name="HealthIconBox" Style="{StaticResource StatIcon}" Background="{StaticResource AmberSoft}"><TextBlock x:Name="HealthIcon" Text="⬡" Foreground="{StaticResource Amber}" FontSize="18" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><TextBlock x:Name="HealthLabel" Text="WINDOWS HEALTH" Foreground="{StaticResource Amber}" FontSize="11" FontWeight="Bold" VerticalAlignment="Center"/></StackPanel><TextBlock x:Name="WindowsStatusText" Text="Checking..." FontSize="23" FontWeight="SemiBold" Margin="0,12,0,2"/><TextBlock x:Name="WindowsStatusHint" Text="Takes a few seconds. Nothing is changed." Style="{StaticResource MutedText}" FontSize="12" TextWrapping="Wrap"/><Button x:Name="HealthCheckButton" Content="↻  Check again" Cursor="Hand" HorizontalAlignment="Left" Margin="0,10,0,0" Visibility="Collapsed" ToolTip="Look again, for example after fixing something. Nothing is changed."><Button.Template><ControlTemplate TargetType="Button"><TextBlock x:Name="LinkText" Text="{TemplateBinding Content}" Foreground="#2563EB" FontSize="13" FontWeight="SemiBold" Background="Transparent"/><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="LinkText" Property="TextDecorations" Value="Underline"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template></Button></StackPanel></Border>
                        </UniformGrid>
<Border x:Name="DashMoreHint" Visibility="Collapsed" Style="{StaticResource Card}" Padding="22,16" Margin="0,0,0,22" BorderBrush="#F08200" BorderThickness="2"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel VerticalAlignment="Center"><TextBlock Text="There are more tools here" FontSize="18" FontWeight="ExtraBold" Foreground="#9A4B00"/><TextBlock Text="Find duplicate files, speed and space, security, drive and memory checks, Hibernate, app updates and more." Style="{StaticResource MutedText}" TextWrapping="Wrap" Margin="0,4,12,0"/></StackPanel><Button x:Name="DashShowAllButton" Grid.Column="1" Style="{StaticResource HeroGreenButton}" Padding="18,10" FontSize="15" FontWeight="Bold" Content="＋  Show all tools" VerticalAlignment="Center"><Button.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#FFC04D" Offset="0"/><GradientStop Color="#F08200" Offset="1"/></LinearGradientBrush></Button.Background></Button></Grid></Border>
<TextBlock x:Name="DashOtherTitle" Text="Other things you can do" FontSize="18" FontWeight="ExtraBold" Margin="0,0,0,10"/>
<UniformGrid x:Name="DashOtherGrid" Columns="3" Margin="0,0,0,14"><Border Style="{StaticResource Card}" Padding="22" Margin="0,0,12,0"><Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><TextBlock Text="Check my PC" FontSize="18" FontWeight="ExtraBold"/><TextBlock Grid.Row="1" Text="Checks your drives (SSD and NVMe too), memory, processor, heat, security, spyware, startup apps and large files in one go. Nothing is changed." Style="{StaticResource MutedText}" TextWrapping="Wrap" Margin="0,6,0,14" MinHeight="40"/><Button Grid.Row="2" VerticalAlignment="Bottom" x:Name="ScanButton" Content="Check my PC" Style="{StaticResource HeroGreenButton}" FontSize="14" Padding="20,9" HorizontalAlignment="Left"><Button.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#4FC3FF" Offset="0"/><GradientStop Color="#1E6FE8" Offset="1"/></LinearGradientBrush></Button.Background></Button></Grid></Border><Border Style="{StaticResource Card}" Padding="22" Margin="0,0,12,0"><Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><TextBlock Text="Past results" FontSize="18" FontWeight="ExtraBold"/><TextBlock Grid.Row="1" Text="Look at what the Cleaner did before." Style="{StaticResource MutedText}" TextWrapping="Wrap" Margin="0,6,0,14" MinHeight="40"/><Button Grid.Row="2" VerticalAlignment="Bottom" x:Name="LastReportButton" Content="See past results" Style="{StaticResource HeroGreenButton}" FontSize="14" Padding="20,9" HorizontalAlignment="Left"><Button.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#3EE0C8" Offset="0"/><GradientStop Color="#0E9F8A" Offset="1"/></LinearGradientBrush></Button.Background></Button></Grid></Border><Border Style="{StaticResource Card}" Padding="22" Margin="0,0,12,0"><Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><TextBlock Text="Update the Cleaner" FontSize="18" FontWeight="ExtraBold"/><TextBlock Grid.Row="1" Text="Look for a newer version of the Cleaner." Style="{StaticResource MutedText}" TextWrapping="Wrap" Margin="0,6,0,14" MinHeight="40"/><Button Grid.Row="2" VerticalAlignment="Bottom" x:Name="CheckUpdatesButton" Content="Update this program" Style="{StaticResource HeroGreenButton}" FontSize="14" Padding="20,9" HorizontalAlignment="Left"><Button.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#FFC04D" Offset="0"/><GradientStop Color="#F08200" Offset="1"/></LinearGradientBrush></Button.Background></Button></Grid></Border></UniformGrid>
<StackPanel x:Name="DashMsTools" Margin="0,0,0,22"><TextBlock Text="MS Tools" FontSize="18" FontWeight="ExtraBold" Margin="0,0,0,10"/><StackPanel Orientation="Horizontal" HorizontalAlignment="Left"><Button x:Name="SmartAppControlButton" Style="{StaticResource HeroGreenButton}" FontSize="14" Padding="20,9" Width="250" Height="46" VerticalAlignment="Top" HorizontalContentAlignment="Center" VerticalContentAlignment="Center" Foreground="White" HorizontalAlignment="Left" Margin="0,0,14,0" ToolTip="Opens the Windows page where Smart App Control is switched on or off. The Cleaner changes nothing itself."><TextBlock Text="Smart App Control" Foreground="White" FontWeight="SemiBold" VerticalAlignment="Center"/></Button><Button x:Name="PCManagerButton" Style="{StaticResource HeroGreenButton}" FontSize="14" Padding="20,9" Width="250" Height="46" VerticalAlignment="Top" HorizontalContentAlignment="Center" VerticalContentAlignment="Center" Foreground="White" HorizontalAlignment="Left" Margin="0,0,0,0" ToolTip="Opens Microsoft PC Manager, or its Microsoft Store page if it is not installed"><StackPanel Orientation="Horizontal" HorizontalAlignment="Center"><Grid Width="22" Height="22" Margin="0,0,10,0" VerticalAlignment="Center" Effect="{DynamicResource DR3DText}"><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition/></Grid.ColumnDefinitions><Grid.RowDefinitions><RowDefinition/><RowDefinition/></Grid.RowDefinitions><Rectangle Margin="0,0,1,1" RadiusX="1.5" RadiusY="1.5" Stroke="#0A5A2C" StrokeThickness="0.6"><Rectangle.Fill><LinearGradientBrush StartPoint="0,0" EndPoint="1,1"><GradientStop Color="#B6FFD2" Offset="0"/><GradientStop Color="#2BE37A" Offset="0.45"/><GradientStop Color="#0B7A3B" Offset="1"/></LinearGradientBrush></Rectangle.Fill></Rectangle><Rectangle Grid.Column="1" Margin="1,0,0,1" RadiusX="1.5" RadiusY="1.5" Stroke="#0A5A2C" StrokeThickness="0.6"><Rectangle.Fill><LinearGradientBrush StartPoint="0,0" EndPoint="1,1"><GradientStop Color="#B6FFD2" Offset="0"/><GradientStop Color="#2BE37A" Offset="0.45"/><GradientStop Color="#0B7A3B" Offset="1"/></LinearGradientBrush></Rectangle.Fill></Rectangle><Rectangle Grid.Row="1" Margin="0,1,1,0" RadiusX="1.5" RadiusY="1.5" Stroke="#0A5A2C" StrokeThickness="0.6"><Rectangle.Fill><LinearGradientBrush StartPoint="0,0" EndPoint="1,1"><GradientStop Color="#B6FFD2" Offset="0"/><GradientStop Color="#2BE37A" Offset="0.45"/><GradientStop Color="#0B7A3B" Offset="1"/></LinearGradientBrush></Rectangle.Fill></Rectangle><Rectangle Grid.Row="1" Grid.Column="1" Margin="1,1,0,0" RadiusX="1.5" RadiusY="1.5" Stroke="#0A5A2C" StrokeThickness="0.6"><Rectangle.Fill><LinearGradientBrush StartPoint="0,0" EndPoint="1,1"><GradientStop Color="#B6FFD2" Offset="0"/><GradientStop Color="#2BE37A" Offset="0.45"/><GradientStop Color="#0B7A3B" Offset="1"/></LinearGradientBrush></Rectangle.Fill></Rectangle></Grid><TextBlock Text="Microsoft PC Manager" Foreground="White" FontWeight="SemiBold" VerticalAlignment="Center"/></StackPanel></Button></StackPanel><TextBlock Text="If it did not do the job, or you want your PC spotless, use DRDirect PC Cleaner for a deeper clean-up." Style="{StaticResource MutedText}" TextWrapping="Wrap" MaxWidth="560" HorizontalAlignment="Left" Margin="0,10,0,0"/></StackPanel>
<Button x:Name="DashNoteButton" Content="Please read first  :)" Style="{StaticResource SecondaryButton}" FontSize="13" Padding="16,8" HorizontalAlignment="Left" Margin="0,4,0,24" ToolTip="Click to read a short, friendly note"/>
<Expander x:Name="DashMoreOptions" Header="More options: choose how deep to clean, and see recent changes" FontSize="14" FontWeight="SemiBold" Margin="0,0,0,18"><StackPanel Margin="0,12,0,0"><Grid Margin="0,0,0,18"><Grid.ColumnDefinitions><ColumnDefinition Width="1*"/><ColumnDefinition Width="1*"/></Grid.ColumnDefinitions>
                            <Grid Margin="0,0,16,10"><Border CornerRadius="14" Background="#16275A" Margin="0,10,0,0" Visibility="{DynamicResource DR3DParts}" IsHitTestVisible="False"/><Border Style="{StaticResource Card}" Padding="22" Margin="0,0,0,10" Effect="{x:Null}">
                                <StackPanel>
                                    <TextBlock Text="HERE IS WHAT WILL CHANGE" Foreground="{StaticResource Blue}" FontSize="11" FontWeight="Bold"/>
                                    <TextBlock x:Name="SafePlanTitle" Text="What Safe mode does" FontSize="18" FontWeight="ExtraBold" Margin="0,6,0,2"/>
                                    <TextBlock Text="Pick a level to see its steps. Nothing has run yet, and you confirm before anything starts." Style="{StaticResource MutedText}" TextWrapping="Wrap"/>
                                    <StackPanel Orientation="Horizontal" Margin="0,10,0,0"><Button x:Name="SafeLevelSafeButton" Content="Easy" Style="{StaticResource SecondaryButton}" Padding="16,6"/><Button x:Name="SafeLevelMediumButton" Content="Deeper" Style="{StaticResource SecondaryButton}" Padding="16,6" Margin="8,0,0,0"/><Button x:Name="SafeLevelAdvancedButton" Content="Expert" Style="{StaticResource SecondaryButton}" Padding="16,6" Margin="8,0,0,0"/></StackPanel>
                                    <StackPanel x:Name="SafePlanList" Margin="0,8,0,6"/>
                                    <TextBlock x:Name="SafePlanNote" Foreground="#667085" FontSize="12" TextWrapping="Wrap" Margin="0,0,0,10"/>
                                    <Button x:Name="SafePlanRunButton" Content="Yes, review and run" Style="{StaticResource PrimaryButton}" HorizontalAlignment="Left"/>
                                </StackPanel>
                            </Border></Grid>
                            <Grid Grid.Column="1" Margin="0,0,0,10"><Border CornerRadius="14" Background="#16275A" Margin="0,10,0,0" Visibility="{DynamicResource DR3DParts}" IsHitTestVisible="False"/><Border Style="{StaticResource Card}" Padding="22" Margin="0,0,0,10" Effect="{x:Null}">
                                <StackPanel>
                                    <Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                                        <TextBlock Text="HISTORY &amp; UNDO" Foreground="{StaticResource Blue}" FontSize="11" FontWeight="Bold" VerticalAlignment="Center"/>
                                        <Button x:Name="DashboardHistoryButton" Grid.Column="1" Content="See all" Style="{StaticResource SecondaryButton}" Padding="12,5"/>
                                    </Grid>
                                    <TextBlock Text="Your recent changes" FontSize="18" FontWeight="ExtraBold" Margin="0,6,0,2"/>
                                    <StackPanel x:Name="DashboardHistoryList" Margin="0,8,0,10"/>
                                    <Button x:Name="UndoAllDashButton" Content="↺  Undo all AI changes" Style="{StaticResource SecondaryButton}" HorizontalAlignment="Left"/>
                                </StackPanel>
                            </Border></Grid>
                        </Grid></StackPanel></Expander>
<Border x:Name="TestModeBanner" Style="{StaticResource Card}" Background="#FFF4E3" BorderBrush="#F0C98C" Margin="0,18,0,0" Visibility="Collapsed"><TextBlock Text="TEST MODE is active. External Windows operations are simulated and file deletion is limited to the supplied test folder." Foreground="{StaticResource Warning}" TextWrapping="Wrap"/></Border>
</StackPanel></ScrollViewer>

                <Grid x:Name="PageTasks" Visibility="Collapsed">
                    <Grid.RowDefinitions><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
                    <!-- The cleanup level box stays at the top; the intro and the task list scroll under it. -->
                    <Grid Grid.Row="0"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
                    <Border x:Name="CleanupPresetPanel" Grid.Row="0" Style="{StaticResource Card}" Padding="16" Margin="0,0,0,14" Visibility="Visible">
                        <StackPanel>
                            <Grid><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel Orientation="Horizontal"><TextBlock Text="Choose cleanup level" FontSize="16" FontWeight="SemiBold"/><Border Background="#E8F0FF" CornerRadius="10" Padding="8,3" Margin="10,0,0,0"><TextBlock Text="ORDERED PRESETS" Foreground="#2563EB" FontSize="11" FontWeight="SemiBold"/></Border></StackPanel><Border Grid.Column="1" Background="#F4F7FF" BorderBrush="#C7D5F5" BorderThickness="1" CornerRadius="10" Padding="8,4" VerticalAlignment="Center"><StackPanel Orientation="Horizontal"><Button x:Name="CleanCheckAllButton" Content="Check all" Style="{StaticResource GlossyChoiceButton}" Padding="18,9" FontSize="14" FontWeight="Bold" Margin="0,0,8,4" ToolTip="Tick every item below, except the cookie item that signs you out"><Button.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#6F8FC4" Offset="0"/><GradientStop Color="#2E4F85" Offset="1"/></LinearGradientBrush></Button.Background></Button><Button x:Name="CleanCheckOffButton" Content="Check off" Style="{StaticResource GlossyChoiceButton}" Padding="18,9" FontSize="14" FontWeight="Bold" Margin="0,0,0,4" ToolTip="Untick every item below"><Button.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#8D9AB0" Offset="0"/><GradientStop Color="#4F5D76" Offset="1"/></LinearGradientBrush></Button.Background></Button></StackPanel></Border></Grid>
                            <TextBlock Text="Safe = regular cleanup. Medium = full cleanup. Advanced = full cleanup plus Windows repair." Style="{StaticResource MutedText}" FontSize="12" Margin="0,4,0,12"/>
