function Start-DRWingetWindow {
    param([string]$WingetArgs, [string]$StartedText)
    if (-not (Get-Command winget -ErrorAction SilentlyContinue)) {
        $answer = [DRDirect.MsgBox]::Show("winget (Windows Package Manager) is not installed on this PC.`n`nInstall it now? The Cleaner downloads Microsoft's own installer (about 20 MB) from aka.ms/getwinget, installs it, then continues.", 'DRDirect PC Cleaner',
            [Windows.MessageBoxButton]::YesNo, [Windows.MessageBoxImage]::Question)
        if ($answer -ne [Windows.MessageBoxResult]::Yes) {
            $ui.AppUpdatesStatus.Text = 'winget is not installed, so apps were not updated.'
            return
        }
        # One console window does everything so progress is visible. If the install
        # fails, it opens Microsoft's download page and the Store page instead.
        $installScript = @"
`$ErrorActionPreference = 'Stop'
`$ProgressPreference = 'SilentlyContinue'
try {
    Write-Host 'Downloading winget from Microsoft...'
    `$file = Join-Path `$env:TEMP 'DRDirect-winget.msixbundle'
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    Invoke-WebRequest -Uri 'https://aka.ms/getwinget' -OutFile `$file -UseBasicParsing
    Write-Host 'Installing winget...'
    Add-AppxPackage -Path `$file
    Remove-Item -LiteralPath `$file -Force -ErrorAction SilentlyContinue
    `$exe = Join-Path `$env:LOCALAPPDATA 'Microsoft\WindowsApps\winget.exe'
    for (`$i = 0; `$i -lt 15 -and -not (Test-Path -LiteralPath `$exe); `$i++) { Start-Sleep -Seconds 1 }
    Write-Host 'winget is installed.'
    Write-Host ''
    & `$exe $WingetArgs
} catch {
    Write-Host ('Could not install winget: ' + `$_.Exception.Message) -ForegroundColor Yellow
    Write-Host 'Opening Microsoft''s download page so you can install it by hand.'
    Start-Process 'https://aka.ms/getwinget'
}
Write-Host ''
Read-Host 'Press Enter to close this window'
"@
        try {
            $encoded = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($installScript))
            Start-Process -FilePath 'powershell.exe' -ArgumentList '-NoProfile', '-ExecutionPolicy', 'Bypass', '-EncodedCommand', $encoded | Out-Null
            $ui.AppUpdatesStatus.Text = 'Installing winget from Microsoft in a console window. It then runs the update by itself.'
        } catch {
            $ui.AppUpdatesStatus.Text = "Could not start the winget install: $($_.Exception.Message)"
        }
        return
    }
    try {
        # Own console window so progress is visible; 'pause' keeps it open to read the result.
        Start-Process -FilePath 'cmd.exe' -ArgumentList "/c winget $WingetArgs & echo. & pause" | Out-Null
        $ui.AppUpdatesStatus.Text = $StartedText
    } catch {
        $ui.AppUpdatesStatus.Text = "Could not start winget: $($_.Exception.Message)"
    }
}

$ui.ListAppUpdatesButton.Add_Click({
    Start-DRWingetWindow 'upgrade --source winget' 'Listing available updates in a console window. Nothing is installed.'
})
function Start-DRFlashyUpgrade {
    # Colourful winget upgrade in its own PowerShell window (live progress, per-app timeout).
    # The script is written to %TEMP% as UTF-8 with BOM so Windows PowerShell reads the emoji correctly.
    $flashy = @'
# Flashy winget upgrade --all  (live progress, per-package timeout)
# Usage: .\winget-upgrade-all.ps1 [-IncludeUnknown] [-NoAnim] [-TimeoutMinutes 45]  (0 = no limit)
param([switch]$IncludeUnknown, [switch]$NoAnim, [int]$TimeoutMinutes = 45)

$ESC = [char]27
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8

function RGB($r, $g, $b, $text) { "$ESC[38;2;${r};${g};${b}m$text$ESC[0m" }
function Hue($i, $n) {
    $h = ($i / [math]::Max($n, 1)) * 6
    $x = [int](255 * (1 - [math]::Abs(($h % 2) - 1)))
    switch ([int][math]::Floor($h) % 6) {
        0 { 255, $x, 0 } 1 { $x, 255, 0 } 2 { 0, 255, $x }
        3 { 0, $x, 255 } 4 { $x, 0, 255 } default { 255, 0, $x }
    }
}
function Rainbow($text, $shift = 0) {
    $n = $text.Length; $out = ''
    for ($i = 0; $i -lt $n; $i++) {
        $c = Hue (($i + $shift) % $n) $n
        $out += RGB $c[0] $c[1] $c[2] $text[$i]
    }
    $out
}

$banner = @(
    '       ____      ____      ____   ___  ____   _____   ____  _____',
    '      |  _ \    |  _ \    |  _ \ |_ _||  _ \ | ____| / ___||_   _|',
    '      | | | |   | |_) |   | | | | | | | |_) ||  _|  | |      | |',
    '      | |_| | _ |  _ <  _ | |_| | | | |  _ < | |___ | |___   | |',
    '      |____/ (_)|_| \_\(_)|____/ |___||_| \_\|_____| \____|  |_|',
    '    _     ____   ____      _   _  ____   ____      _     _____  _____  ____',
    '   / \   |  _ \ |  _ \    | | | ||  _ \ |  _ \    / \   |_   _|| ____||  _ \',
    '  / _ \  | |_) || |_) |   | | | || |_) || | | |  / _ \    | |  |  _|  | |_) |',
    ' / ___ \ |  __/ |  __/    | |_| ||  __/ | |_| | / ___ \   | |  | |___ |  _ <',
    '/_/   \_\|_|    |_|        \___/ |_|    |____/ /_/   \_\  |_|  |_____||_| \_\',
    '     ✦  K E E P I N G   Y O U R   A P P S   F R E S H  ✦'
)

# Centre each block of the banner (and the tagline) in the same width so the two words line up.
function Center-Block([string[]]$lines, [int]$width) {
    $indent = ($lines | ForEach-Object { $_.Length - $_.TrimStart().Length } | Measure-Object -Minimum).Minimum
    $trimmed = @($lines | ForEach-Object { $_.Substring($indent).TrimEnd() })
    $bw = ($trimmed | Measure-Object -Property Length -Maximum).Maximum
    $pad = ' ' * [Math]::Max(0, [int][Math]::Floor(($width - $bw) / 2))
    $trimmed | ForEach-Object { $pad + $_ }
}
$bannerWidth = 78
$banner = @(Center-Block $banner[0..4] $bannerWidth) + @(Center-Block $banner[5..9] $bannerWidth) + @(Center-Block @($banner[10]) $bannerWidth)

try { Clear-Host } catch {}
$frames = if ($NoAnim) { 1 } else { 24 }
for ($f = 0; $f -lt $frames; $f++) {
    if ($f -gt 0) { try { [Console]::SetCursorPosition(0, 0) } catch {} }
    Write-Host ''
    # The D.R.Direct APP Updater letters are solid bright green; the tagline (last line, bold) is bright blue.
    foreach ($line in $banner) {
        if ($line -like '*K E E P I N G*') { Write-Host ("$ESC[1m" + (RGB 0 160 255 $line)) }
        else { Write-Host (RGB 0 255 0 $line) }
    }
    Write-Host ''
    if (-not $NoAnim) { Start-Sleep -Milliseconds 40 }
}
Write-Host (RGB 0 255 80 ('═' * $bannerWidth))
Write-Host ''

if (-not (Get-Command winget -ErrorAction SilentlyContinue)) {
    Write-Host (RGB 255 60 90 '💥 winget not found. Install "App Installer" from the Microsoft Store.')
    Read-Host 'Press Enter to close' | Out-Null
    exit 1
}

# ---- 0. make sure PowerShell 7 and Windows Terminal are installed -----------
# Both come from winget and keep themselves current through the upgrade below.
# Only a clear "not installed" answer triggers an install; if winget cannot tell
# (no network, source down), nothing is installed.
$essentials = @(
    # Present: winget does not always know about a copy that was installed another way,
    # so look for the program itself before deciding it is missing.
    @{ Name = 'PowerShell 7';      Id = 'Microsoft.PowerShell'
       Present = { (Test-Path -LiteralPath (Join-Path $env:ProgramFiles 'PowerShell\7\pwsh.exe')) -or [bool](Get-Command pwsh.exe -ErrorAction SilentlyContinue) } },
    @{ Name = 'Windows Terminal';  Id = 'Microsoft.WindowsTerminal'
       Present = { [bool](Get-Command wt.exe -ErrorAction SilentlyContinue) -or [bool](Get-AppxPackage -AllUsers -Name 'Microsoft.WindowsTerminal*' -ErrorAction SilentlyContinue) } }
)
$wingetPath = (Get-Command winget).Source
$ok = @(); $fail = @()
foreach ($e in $essentials) {
    if (& $e.Present) { continue }
    $null = & $wingetPath list --id $e.Id --exact --accept-source-agreements 2>&1
    if ($LASTEXITCODE -ne -1978335212) { continue }   # installed, or winget could not tell
    Write-Host (RGB 0 255 200 "🧰 $($e.Name) is not installed - installing it...")
    $a = @('install', '--id', $e.Id, '--exact', '--silent', '--accept-source-agreements', '--accept-package-agreements')
    $proc = Start-Process $wingetPath -ArgumentList $a -NoNewWindow -PassThru
    $null = $proc.Handle
    if (-not $proc.WaitForExit($(if ($TimeoutMinutes -gt 0) { $TimeoutMinutes * 60000 } else { -1 }))) {
        try { Stop-Process -Id $proc.Id -Force } catch {}
        Write-Host (RGB 255 60 90 "⏰ $($e.Name) timed out after ${TimeoutMinutes}m - skipped")
        $fail += "$($e.Name) (timeout)"
    }
    elseif ($proc.ExitCode -eq 0) {
        Write-Host (RGB 80 255 120 "✅ $($e.Name) installed")
        $ok += "$($e.Name) (installed)"
    }
    elseif ($proc.ExitCode -in -1978335135, -1978335189) {
        # Already there under another name, or this PC cannot run it. Nothing to report.
        Write-Host (RGB 150 150 255 "⏭️  $($e.Name) - not needed on this PC")
    }
    else {
        Write-Host (RGB 255 60 90 "💥 $($e.Name) could not be installed (exit code $($proc.ExitCode))")
        $fail += "$($e.Name) (exit $($proc.ExitCode))"
    }
}
Write-Host ''

# ---- 1. find what needs upgrading -------------------------------------------
Write-Host (RGB 0 255 200 '🔎 Checking for upgrades...')
$listArgs = @('upgrade', '--accept-source-agreements')
if ($IncludeUnknown) { $listArgs += '--include-unknown' }
$raw = (& winget @listArgs 2>&1 | Out-String) -split "`r?`n"

$pkgs = @(); $idCol = -1; $verCol = -1; $availCol = -1; $srcCol = -1; $inTable = $false
foreach ($l in $raw) {
    $l = ($l -split "`r")[-1]                       # drop spinner prefixes
    if ($l -match '^Name\s+Id\s+Version') {
        if ($pkgs.Count -gt 0) { break }            # 2nd table = needs explicit targeting
        $idCol = $l.IndexOf('Id'); $verCol = $l.IndexOf('Version'); $inTable = $false
        $availCol = $l.IndexOf('Available'); $srcCol = $l.IndexOf('Source')
        continue
    }
    if ($idCol -ge 0 -and $l -match '^-{5,}') { $inTable = $true; continue }
    if ($inTable) {
        if ($l -match 'upgrades? available' -or $l.Trim() -eq '') { $inTable = $false; continue }
        if ($l.Length -gt $verCol) {
            $offered = ''
            if ($availCol -gt $verCol -and $l.Length -gt $availCol) {
                $end = if ($srcCol -gt $availCol -and $l.Length -ge $srcCol) { $srcCol } else { $l.Length }
                $offered = $l.Substring($availCol, $end - $availCol).Trim()
            }
            $pkgs += [pscustomobject]@{
                Name      = $l.Substring(0, $idCol).Trim()
                Id        = $l.Substring($idCol, $verCol - $idCol).Trim()
                Available = $offered
            }
        }
    }
}

# Windows Update or an installer can put a newer PowerShell 7 on this PC than winget has on record, and winget
# then offers a version that is already here. Compare with the copy that is really installed and leave it be.
foreach ($ps7 in @($pkgs | Where-Object { $_.Id -eq 'Microsoft.PowerShell' -and $_.Available })) {
    try {
        $pwshExe = Join-Path $env:ProgramFiles 'PowerShell\7\pwsh.exe'
        if (-not (Test-Path -LiteralPath $pwshExe)) { $pwshExe = (Get-Command pwsh.exe -ErrorAction Stop).Source }
        $toVersion = { param($t) $n = @(($t -replace '[^0-9.].*$', '') -split '\.') + '0', '0', '0', '0'; [version]($n[0..3] -join '.') }
        $have = & $toVersion (Get-Item -LiteralPath $pwshExe).VersionInfo.ProductVersion
        $offer = & $toVersion $ps7.Available
        if ($have -ge $offer) {
            Write-Host (RGB 150 150 255 "⏭️  $($ps7.Name) - version $have is already installed, winget just has not caught up")
            $pkgs = @($pkgs | Where-Object { $_.Id -ne 'Microsoft.PowerShell' })
        }
    } catch { }
}

# Apps left out on purpose: Warp updates itself and its download stalls; Logitech G HUB updates itself and
# winget misreads its version, so it was offered again right after every successful update.
# App Installer is winget itself: winget cannot update itself while it runs (0x800704c7), and the
# Microsoft Store keeps it current anyway.
$skipIds = @('Warp.Warp', 'Logitech.GHUB', 'Microsoft.AppInstaller')
# Adobe Express Photos is not used here and its download keeps failing winget's checksum check.
$skipName = 'Adobe Express*'
foreach ($s in @($pkgs | Where-Object { ($skipIds -contains $_.Id) -or ($_.Name -like $skipName) })) {
    Write-Host (RGB 150 150 255 "⏭️  Skipping $($s.Name) [$($s.Id)]")
}
$pkgs = @($pkgs | Where-Object { ($skipIds -notcontains $_.Id) -and ($_.Name -notlike $skipName) })
# Adobe Acrobat Reader: the Microsoft Store listing cannot update a copy that came from Adobe's own installer
# ("install technology is different"). Adobe's installer package in the winget source can, so use that one.
$acroId = 'Adobe.Acrobat.Reader.64-bit'
$seenIds = @{}
$pkgs = @($pkgs | ForEach-Object {
    if ($_.Id -eq 'XPDP273C0XHQH2' -or ($_.Name -like 'Adobe Acrobat*' -and $_.Id -notlike 'Adobe.*')) { [pscustomobject]@{ Name = $_.Name; Id = $acroId } } else { $_ }
} | Where-Object { if ($seenIds.ContainsKey($_.Id)) { $false } else { $seenIds[$_.Id] = $true; $true } })
if ($pkgs.Count -eq 0) {
    Write-Host (RGB 150 150 255 '😎 Everything is already up to date!')
    Read-Host 'Press Enter to close' | Out-Null
    exit 0
}

Write-Host (RGB 255 160 0 "📦 $($pkgs.Count) packages to upgrade:")
$pkgs | ForEach-Object { Write-Host (RGB 255 0 200 "   ✨ $($_.Name) ") -NoNewline; Write-Host (RGB 150 150 255 "[$($_.Id)]") }
Write-Host ''

$wingetExe = (Get-Command winget).Source
# ---- 2. upgrade each one with live winget progress --------------------------
$start = Get-Date; $i = 0
foreach ($p in $pkgs) {
    $i++
    Write-Host (RGB 0 255 80 ('-' * 90))
    Write-Host (RGB 255 230 0 "⚡ [$i/$($pkgs.Count)] $($p.Name)") -NoNewline
    Write-Host (RGB 150 150 255 "  [$($p.Id)]  ($(if ($TimeoutMinutes -gt 0) { "up to ${TimeoutMinutes} min" } else { 'no time limit' }))")

    $a = @('upgrade', '--id', $p.Id, '--exact', '--silent', '--accept-source-agreements', '--accept-package-agreements')
    if ($p.Id -eq $acroId) { $a += @('--source', 'winget') }
    $proc = Start-Process $wingetExe -ArgumentList $a -NoNewWindow -PassThru   # shares console => real progress bar
    $null = $proc.Handle   # without this, ExitCode comes back empty after a timed WaitForExit
    $done = $proc.WaitForExit($(if ($TimeoutMinutes -gt 0) { $TimeoutMinutes * 60000 } else { -1 }))
    if (-not $done) {
        try { Stop-Process -Id $proc.Id -Force } catch {}
        Write-Host (RGB 255 60 90 "⏰ $($p.Name) timed out after ${TimeoutMinutes}m - skipped")
        $fail += "$($p.Name) (timeout)"
    }
    elseif ($proc.ExitCode -eq -1978335090) {
        # Installed with a different installer type than winget updates with (e.g. an old Store copy).
        # Nothing is broken and the app is untouched, so it is not reported as a problem.
        Write-Host (RGB 150 150 255 "⏭️  $($p.Name) - installed by its own installer, so it updates itself. Nothing to uninstall, kept current one")
    }
    elseif ($proc.ExitCode -eq -1978335189) {
        # The newer version does not fit this PC (architecture or requirements). The
        # installed copy is untouched and fine, so this is not a problem either.
        Write-Host (RGB 150 150 255 "⏭️  $($p.Name) - newer version does not apply to this PC, kept current one")
    }
    elseif ($proc.ExitCode -eq 0) {
        Write-Host (RGB 80 255 120 "✅ $($p.Name) upgraded")
        $ok += $p.Name
    }
    elseif ($proc.ExitCode -eq -1978335212 -and $p.Name -like 'PowerShell 7*') {
        # PowerShell 7 was put on by hand, so winget lists it as out of date but cannot upgrade it by that name.
        # Installing the winget package over it brings it up to date and lets winget look after it from now on.
        Write-Host (RGB 0 255 200 "🧰 $($p.Name) was not installed through winget - bringing it under winget...")
        $ia = @('install', '--id', 'Microsoft.PowerShell', '--exact', '--silent', '--accept-source-agreements', '--accept-package-agreements')
        $iproc = Start-Process $wingetExe -ArgumentList $ia -NoNewWindow -PassThru
        $null = $iproc.Handle
        if (-not $iproc.WaitForExit($(if ($TimeoutMinutes -gt 0) { $TimeoutMinutes * 60000 } else { -1 }))) {
            try { Stop-Process -Id $iproc.Id -Force } catch {}
            Write-Host (RGB 255 60 90 "⏰ PowerShell 7 timed out after ${TimeoutMinutes}m - skipped")
            $fail += 'PowerShell 7 (timeout)'
        }
        elseif ($iproc.ExitCode -eq 0) {
            Write-Host (RGB 80 255 120 '✅ PowerShell 7 is now installed through winget and up to date')
            $ok += 'PowerShell 7'
        }
        elseif ($iproc.ExitCode -in -1978335135, -1978335189) {
            Write-Host (RGB 150 150 255 '⏭️  PowerShell 7 - already current, kept as it is')
        }
        else {
            Write-Host (RGB 255 60 90 "💥 PowerShell 7 failed (exit code $($iproc.ExitCode))")
            $fail += "PowerShell 7 (exit $($iproc.ExitCode))"
        }
    }
    elseif ($proc.ExitCode -eq -1978335212 -and $p.Id -eq $acroId) {
        # This copy of Acrobat Reader came from the Microsoft Store, which keeps it current by itself.
        Write-Host (RGB 150 150 255 "⏭️  $($p.Name) - installed from the Microsoft Store, so the Store updates it. Nothing to do")
    }
    else {
        Write-Host (RGB 255 60 90 "💥 $($p.Name) failed (exit code $($proc.ExitCode))")
        $fail += "$($p.Name) (exit $($proc.ExitCode))"
    }
}

# ---- 3. summary -------------------------------------------------------------
$secs = [int]((Get-Date) - $start).TotalSeconds
Write-Host ''
Write-Host (RGB 0 255 80 ('═' * $bannerWidth))
Write-Host (RGB 80 255 120 "🎉 Done in ${secs}s") -NoNewline
Write-Host (RGB 255 230 0 "   ✅ $($ok.Count) upgraded") -NoNewline
if ($fail.Count -eq 0) { Write-Host (RGB 80 255 120 "   ✅ no problems") }
else { Write-Host (RGB 255 60 90 "   💥 $($fail.Count) problems") }
foreach ($f in $fail) { Write-Host (RGB 255 60 90 "   - $f") }
Write-Host (RGB 0 255 80 ('=' * 90))
Write-Host ''
Read-Host 'Press Enter to close' | Out-Null

'@
    # French: the update window's own lines in French too (winget's lines follow the Windows language).
    $drFlashyTitle = 'DRDirect App Updater'
    if (('DRDirect.Lang' -as [type]) -and [DRDirect.Lang]::French) {
        $drFlashyTitle = 'DRDirect - Mise à jour des applications'
        foreach ($kv in @(
        @('''     ✦  K E E P I N G   Y O U R   A P P S   F R E S H  ✦''', '''     ✦  V O S   A P P S   T O U J O U R S   À   J O U R  ✦'''),
        @('-like ''*K E E P I N G*''', '-like ''*✦*'''),
        @('''💥 winget not found. Install "App Installer" from the Microsoft Store.''', '''💥 winget introuvable. Installez « App Installer » depuis le Microsoft Store.'''),
        @('''Press Enter to close''', '''Appuyez sur Entrée pour fermer'''),
        @(' is not installed - installing it..."', ' n’’est pas installé - installation..."'),
        @(' timed out after ${TimeoutMinutes}m - skipped"', ' : délai de ${TimeoutMinutes} min dépassé - ignoré"'),
        @('(timeout)', '(délai dépassé)'),
        @('✅ $($e.Name) installed"', '✅ $($e.Name) installé"'),
        @(' - not needed on this PC"', ' - pas nécessaire sur ce PC"'),
        @(' could not be installed (exit code ', ' n’’a pas pu être installé (code de sortie '),
        @('''🔎 Checking for upgrades...''', '''🔎 Recherche des mises à jour...'''),
        @(' - version $have is already installed, winget just has not caught up"', ' - la version $have est déjà installée, winget n’’est simplement pas encore à jour"'),
        @('⏭️  Skipping $($s.Name)', '⏭️  Ignoré : $($s.Name)'),
        @('''😎 Everything is already up to date!''', '''😎 Tout est déjà à jour !'''),
        @(' packages to upgrade:"', ' applications à mettre à jour :"'),
        @('"up to ${TimeoutMinutes} min"', '"jusqu’’à ${TimeoutMinutes} min"'),
        @('''no time limit''', '''sans limite de temps'''),
        @(' - installed by its own installer, so it updates itself. Nothing to uninstall, kept current one"', ' - installé par son propre installateur, il se met donc à jour seul. Rien à désinstaller, version actuelle gardée"'),
        @(' - newer version does not apply to this PC, kept current one"', ' - la nouvelle version ne s’’applique pas à ce PC, version actuelle gardée"'),
        @('✅ $($p.Name) upgraded"', '✅ $($p.Name) mis à jour"'),
        @(' was not installed through winget - bringing it under winget..."', ' n’’a pas été installé par winget - prise en charge par winget..."'),
        @('''✅ PowerShell 7 is now installed through winget and up to date''', '''✅ PowerShell 7 est maintenant installé par winget et à jour'''),
        @('''⏭️  PowerShell 7 - already current, kept as it is''', '''⏭️  PowerShell 7 - déjà à jour, gardé tel quel'''),
        @(' failed (exit code ', ' a échoué (code de sortie '),
        @('(exit $(', '(code $('),
        @(' - installed from the Microsoft Store, so the Store updates it. Nothing to do"', ' - installé depuis le Microsoft Store, c’’est donc le Store qui le met à jour. Rien à faire"'),
        @('"🎉 Done in ${secs}s"', '"🎉 Terminé en ${secs} s"'),
        @(' upgraded") -NoNewline', ' mis à jour") -NoNewline'),
        @('"   ✅ no problems"', '"   ✅ aucun problème"'),
        @(' problems")', ' problèmes")')
        )) { $flashy = $flashy.Replace($kv[0], $kv[1]) }
    }
    try {
        $file = Join-Path $env:TEMP 'DRDirect-Winget-Upgrade.ps1'
        [IO.File]::WriteAllText($file, $flashy, (New-Object Text.UTF8Encoding $true))
        # 'start' forces a real new console window, like the cmd route that always showed one; the script itself waits for Enter before it closes, on every path.
        Start-Process -FilePath 'cmd.exe' -ArgumentList ('/c start "' + $drFlashyTitle + '" powershell.exe -NoProfile -ExecutionPolicy Bypass -File "' + $file + '"') -WindowStyle Hidden | Out-Null
        $ui.AppUpdatesStatus.Text = 'Updating apps in a colour PowerShell window. Close it when it says it has finished.'
    } catch {
        $ui.AppUpdatesStatus.Text = "Could not start the update window: $($_.Exception.Message)"
    }
}
function Invoke-DRUpdateAllApps {
    $answer = [DRDirect.MsgBox]::Show("This runs 'winget upgrade --all' and updates every app winget can update on this PC.`n`nIt also installs PowerShell 7 and Windows Terminal if this PC does not have them.`n`nSome apps may close or restart during their update. Save your work first.`n`nContinue?", 'DRDirect PC Cleaner',
        [Windows.MessageBoxButton]::YesNo, [Windows.MessageBoxImage]::Question)
    if ($answer -ne [Windows.MessageBoxResult]::Yes) { return }
    if (Get-Command winget -ErrorAction SilentlyContinue) { Start-DRFlashyUpgrade; return }
    Start-DRWingetWindow 'upgrade --all --silent --accept-source-agreements --accept-package-agreements' 'Updating apps in a console window. Close it when it says it has finished.'
}
function Resolve-DRUninstallerExe {
    # The DRDirect Uninstaller ships in its own folder beside the Cleaner. It is a
    # separate program (based on Bulk Crap Uninstaller, Apache 2.0) that asks before
    # it removes anything, and it never touches the internet.
    $roots = New-Object System.Collections.Generic.List[string]
    try {
        $exe = [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
        if (-not [string]::IsNullOrWhiteSpace($exe)) { $roots.Add((Split-Path -Parent $exe)) }
    } catch { }
    if (-not [string]::IsNullOrWhiteSpace($PSScriptRoot)) { $roots.Add($PSScriptRoot) }
    try {
        if (-not [string]::IsNullOrWhiteSpace([AppDomain]::CurrentDomain.BaseDirectory)) {
            $roots.Add([AppDomain]::CurrentDomain.BaseDirectory)
        }
    } catch { }
    # An updated interface runs as a script from the Scripts folder under AppData, so
    # "beside this script" is not where the user keeps the Cleaner. The program that
    # started it is, so walk up through the programs that launched this one.
    try {
        $walkId = $PID
        for ($level = 0; $level -lt 6 -and $walkId; $level++) {
            $info = Get-CimInstance -ClassName Win32_Process -Filter "ProcessId=$walkId" -ErrorAction Stop
            if (-not $info) { break }
            if ($level -gt 0 -and -not [string]::IsNullOrWhiteSpace($info.ExecutablePath)) {
                $roots.Add((Split-Path -Parent $info.ExecutablePath))
            }
            $walkId = [int]$info.ParentProcessId
            if ($walkId -le 4) { break }
        }
    } catch { }
    # The Cleaner unpacks its own copy here the first time it starts, so this is the usual place.
    if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        # Its proper name first; older packages only have BCUninstaller.exe.
        foreach ($exeName in 'DRDirect Uninstaller.exe', 'BCUninstaller.exe') {
            $unpacked = Join-Path $env:LOCALAPPDATA ('DRDirect PC Cleaner\Uninstaller\' + $exeName)
            if (Test-Path -LiteralPath $unpacked -PathType Leaf) { return $unpacked }
        }
    }
    foreach ($root in @($roots | Select-Object -Unique)) {
        if ([string]::IsNullOrWhiteSpace($root)) { continue }
        foreach ($exeName in 'DRDirect Uninstaller.exe', 'BCUninstaller.exe') {
            $candidate = Join-Path -Path $root -ChildPath ('DRDirect Uninstaller\' + $exeName)
            if (Test-Path -LiteralPath $candidate -PathType Leaf) { return $candidate }
        }
    }
    return $null
}

function Show-DRRunningUninstaller {
    # Going back and forth must never start over. If this uninstaller is already open
    # (even minimised), bring that same window forward instead of opening a second one
    # that would have to scan every program again.
    param([string]$UninstallerPath)
    try {
        $ours = @(Get-CimInstance -ClassName Win32_Process -Filter "Name='BCUninstaller.exe' OR Name='DRDirect Uninstaller.exe'" -ErrorAction Stop |
            Where-Object { $_.ExecutablePath -and ($_.ExecutablePath -ieq $UninstallerPath) })
    } catch { return $false }
    foreach ($candidate in $ours) {
        $process = Get-Process -Id $candidate.ProcessId -ErrorAction SilentlyContinue
        if (-not $process -or $process.MainWindowHandle -eq 0) { continue }
        if (-not ('DRFrontWindow' -as [type])) {
            Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class DRFrontWindow {
    [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr window, int command);
    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr window);
    [DllImport("user32.dll")] public static extern bool IsIconic(IntPtr window);
}
'@
        }
        $handle = $process.MainWindowHandle
        if ([DRFrontWindow]::IsIconic($handle)) { [void][DRFrontWindow]::ShowWindow($handle, 9) }
        [void][DRFrontWindow]::SetForegroundWindow($handle)
        return $true
    }
    return $false
}

function Get-DRCleanerLauncherPath {
    # The program file that started this Cleaner, so the uninstaller's "Back to the
    # Cleaner" button can start it again if it was closed in the meantime.
    try {
        $walkId = $PID
        for ($level = 0; $level -lt 6 -and $walkId; $level++) {
            $info = Get-CimInstance -ClassName Win32_Process -Filter "ProcessId=$walkId" -ErrorAction Stop
            if (-not $info) { break }
            if ($info.ExecutablePath -and ([IO.Path]::GetFileName($info.ExecutablePath) -like 'DRDirect PC Cleaner*.exe')) { return $info.ExecutablePath }
            $walkId = [int]$info.ParentProcessId
            if ($walkId -le 4) { break }
        }
    } catch { }
    return $null
}

$script:DRUninstallerUpdateTried = $false

function Start-DRUninstallerUpdate {
    # Returns $true when the update was started; Open-DRUninstaller is called again when it ends.
    try {
        # The updater is built into the exe, not a file a new runspace could load,
        # so hand over its functions and settings as they are.
        $names = 'ConvertFrom-DRPkcs1PublicKey', 'Test-DRManifestSignature', 'Get-DRUpdateRoot', 'Get-DRInstalledVersion',
            'Clear-DRStaleTemp', 'Get-DRFileHashWithRetry', 'Invoke-DRFeedWeb', 'Update-DRUninstallerFromFeed'
        $code = ($names | ForEach-Object { "function $_ {`r`n$((Get-Command $_ -CommandType Function).Definition)`r`n}" }) -join "`r`n"

        $script:DRUnUpdateRunspace = [RunspaceFactory]::CreateRunspace()
        $script:DRUnUpdateRunspace.Open()
        foreach ($name in 'DRUpdateFeed', 'DRUpdateRef', 'DRUpdateHeaders', 'DRUpdateMirror', 'DRUpdatePublicKey') {
            $script:DRUnUpdateRunspace.SessionStateProxy.SetVariable($name, (Get-Variable -Name $name -Scope Script -ValueOnly))
        }
        $script:DRUnUpdatePs = [PowerShell]::Create()
        $script:DRUnUpdatePs.Runspace = $script:DRUnUpdateRunspace
        $null = $script:DRUnUpdatePs.AddScript("Set-StrictMode -Version 2.0`r`n$code`r`nUpdate-DRUninstallerFromFeed")
        $script:DRUnUpdateAsync = $script:DRUnUpdatePs.BeginInvoke()
    } catch {
        return $false
    }

    $ui.OverlayContinueButton.Visibility = 'Collapsed'
    $ui.OverlayPercent.Visibility = 'Collapsed'
    $ui.OverlayProgress.IsIndeterminate = $true
    $ui.OverlayTitle.Text = 'Updating the Uninstaller'
    $ui.OverlayMessage.Text = 'Getting the new version of the DRDirect Uninstaller Program. ' +
        'This only happens once after an update and can take up to a minute. Please wait...'
    $ui.BusyOverlay.Visibility = 'Visible'

    # Script scope: the timer's handler runs in its own scope, and StrictMode stops on anything it cannot see.
    $script:DRUnUpdateTimer = New-Object Windows.Threading.DispatcherTimer
    $script:DRUnUpdateTimer.Interval = [TimeSpan]::FromMilliseconds(300)
    $script:DRUnUpdateTimer.Add_Tick({
        if (-not $script:DRUnUpdateAsync.IsCompleted) { return }
        $script:DRUnUpdateTimer.Stop()
        try {
            $null = $script:DRUnUpdatePs.EndInvoke($script:DRUnUpdateAsync)
        } catch { }
        try {
            $script:DRUnUpdatePs.Dispose()
            $script:DRUnUpdateRunspace.Close()
            $script:DRUnUpdateRunspace.Dispose()
        } catch { }
        $ui.BusyOverlay.Visibility = 'Collapsed'
        $ui.OverlayProgress.IsIndeterminate = $false
        $ui.OverlayPercent.Visibility = 'Visible'
        # Whether it worked or not, open the Uninstaller that is now there.
        $script:DRUninstallerUpdateTried = $true
        Open-DRUninstaller
    })
    $script:DRUnUpdateTimer.Start()
    return $true
}

function Grant-DRUninstallerFolderAccess {
    # Windows "Controlled folder access" (ransomware protection) blocks programs it does not
    # know from changing files in Documents, Desktop and so on, so the Uninstaller could not
    # remove leftovers there. When it is on and the Uninstaller is not allowed yet, ask once.
    param([string]$UninstallerPath)
    try {
        if ($script:DRCfaAsked) { return }
        $pref = Get-MpPreference -ErrorAction Stop
        if ([int]$pref.EnableControlledFolderAccess -ne 1) { return }
        $allowed = @($pref.ControlledFolderAccessAllowedApplications) | Where-Object { $_ }
        if ($allowed | Where-Object { $_ -ieq $UninstallerPath }) { return }
        $script:DRCfaAsked = $true
        $answer = [DRDirect.MsgBox]::Show(
            "Windows ransomware protection (Controlled folder access) is on, so it will stop the DRDirect Uninstaller from removing leftovers in folders like Documents and Desktop." +
            [Environment]::NewLine + [Environment]::NewLine + "Allow the DRDirect Uninstaller through Controlled folder access?",
            'DRDirect PC Cleaner', [Windows.MessageBoxButton]::YesNo, [Windows.MessageBoxImage]::Question)
        if ($answer -ne [Windows.MessageBoxResult]::Yes) { return }
        Add-MpPreference -ControlledFolderAccessAllowedApplications $UninstallerPath -ErrorAction Stop
    } catch { }
}

$script:DRNewUninstallerSha = '8811AD2C13EA38BCAE0DF6A0405C3505785F9520B91BA60537A3E81BC80FB49C'
$script:DRNewUninstallerGz = ''
function Get-DRNewUninstallerBytes {
    $packed = [Convert]::FromBase64String($script:DRNewUninstallerGz)
    $in = New-Object IO.MemoryStream(, $packed)
    $gz = New-Object IO.Compression.GZipStream($in, [IO.Compression.CompressionMode]::Decompress)
    $out = New-Object IO.MemoryStream
    try { $gz.CopyTo($out) } finally { $gz.Dispose(); $in.Dispose() }
    return , $out.ToArray()
}
function Install-DRNewUninstaller([string]$Path) {
    # True when the copy at $Path is exactly the one this Cleaner carries (written now if needed).
    $sha = [Security.Cryptography.SHA256]::Create()
    try {
        if (Test-Path -LiteralPath $Path -PathType Leaf) {
            $have = -join ($sha.ComputeHash([IO.File]::ReadAllBytes($Path)) | ForEach-Object { $_.ToString('X2') })
            if ($have -eq $script:DRNewUninstallerSha) { return $true }
        }
        $bytes = Get-DRNewUninstallerBytes
        $got = -join ($sha.ComputeHash($bytes) | ForEach-Object { $_.ToString('X2') })
        if ($got -ne $script:DRNewUninstallerSha) { return $false }
        $dir = Split-Path -Parent $Path
        if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        $tmp = $Path + '.new'
        [IO.File]::WriteAllBytes($tmp, $bytes)
        Move-Item -LiteralPath $tmp -Destination $Path -Force
        return $true
    } finally { $sha.Dispose() }
}
function Open-DRUninstaller {
    if (Test-DROtherToolBusy -Opening 'Uninstaller') { return }
    if ($TestMode) {
        # Test mode unpacks the copy this Cleaner carries into the build folder and opens it in its own test mode.
        $drTestScript = Join-Path $PSScriptRoot 'build
ew-uninstaller\DRDirect Uninstaller.ps1'
        $drOk = $false
        try { $drOk = Install-DRNewUninstaller -Path $drTestScript } catch { $drOk = $false; $drErr = $_.Exception.Message }
        if (-not $drOk) {
            [DRDirect.MsgBox]::Show("Test mode: the new uninstaller could not be unpacked. $drErr", 'DRDirect PC Cleaner') | Out-Null
            return
        }
        if (Test-Path -LiteralPath $drTestScript) {
            try {
                Start-Process -FilePath 'powershell.exe' -WorkingDirectory (Split-Path -Parent $drTestScript) -ArgumentList @(
                    '-NoProfile', '-STA', '-ExecutionPolicy', 'Bypass', '-WindowStyle', 'Hidden', '-File', ('"' + $drTestScript + '"'), '-Test')
            } catch { }
            return
        }
        [DRDirect.MsgBox]::Show('Test mode: the DRDirect Uninstaller Program would open here.', 'DRDirect PC Cleaner',
            [Windows.MessageBoxButton]::OK, [Windows.MessageBoxImage]::Information) | Out-Null
        return
    }
    # The Uninstaller has its own key. The launcher says whether this PC already has one.
    if ($env:DRDIRECT_UNINSTALLER_OK -eq '0') {
        if ((Show-DRActivation 'locked' 'DRDirect Uninstaller') -ne 'activated') { return }
        $env:DRDIRECT_UNINSTALLER_OK = '1'
    }
    # An accepted update may carry a newer Uninstaller. Put it in place before it opens.
    # It can take a minute, so it runs in the background behind a "please wait" overlay,
    # and opening carries on once it is done. It is tried once per click.
    if (-not $script:DRUninstallerUpdateTried -and
        (Get-Command Update-DRUninstallerFromFeed -ErrorAction SilentlyContinue) -and
        (Update-DRUninstallerFromFeed -CheckOnly)) {
        if (Start-DRUninstallerUpdate) { return }
    }
    # DRDirect's own new uninstaller. It is used only on a PC that has been switched over to it
    # (the marker file beside it); every other PC keeps opening the uninstaller below.
    $newDir = Join-Path $env:LOCALAPPDATA 'DRDirect PC Cleaner\DRDirect Uninstaller'
    $newScript = Join-Path $newDir 'DRDirect Uninstaller.ps1'
    # It is carried inside the Cleaner, so every PC has it: written out here when missing or older.
    # If that cannot be done, the old uninstaller below still opens.
    $drNewReady = $false
    try { $drNewReady = Install-DRNewUninstaller -Path $newScript } catch { }
    if ($drNewReady) {
        try {
            $launcher = Get-DRCleanerLauncherPath
            if ($launcher) { $env:DRDIRECT_CLEANER_EXE = $launcher }
            $env:DRDIRECT_UNINSTALLER_OK = '1'   # the key was checked above
            Start-Process -FilePath 'powershell.exe' -WorkingDirectory $newDir -ArgumentList @(
                '-NoProfile', '-STA', '-ExecutionPolicy', 'Bypass', '-WindowStyle', 'Hidden', '-File', ('"' + $newScript + '"'))
        } catch {
            [DRDirect.MsgBox]::Show("Could not open the DRDirect Uninstaller Program: $($_.Exception.Message)", 'DRDirect PC Cleaner',
                [Windows.MessageBoxButton]::OK, [Windows.MessageBoxImage]::Error) | Out-Null
        }
        return
    }
    $script:DRUninstallerUpdateTried = $false
    $uninstaller = Resolve-DRUninstallerExe
    if (-not $uninstaller) {
        [DRDirect.MsgBox]::Show(
            "The DRDirect Uninstaller Program was not found beside the Cleaner." + [Environment]::NewLine + [Environment]::NewLine +
            "Keep the 'DRDirect Uninstaller' folder in the same folder as the Cleaner, then try again.",
            'DRDirect PC Cleaner', [Windows.MessageBoxButton]::OK, [Windows.MessageBoxImage]::Information) | Out-Null
        return
    }
    if (Show-DRRunningUninstaller -UninstallerPath $uninstaller) { return }
    Grant-DRUninstallerFolderAccess -UninstallerPath $uninstaller
    try {
        # Its own setting (beside it) says which language it shows: the one chosen in the Cleaner.
        try {
            $drSet = Join-Path (Split-Path -Parent $uninstaller) 'BCUninstaller.settings'
            if (Test-Path -LiteralPath $drSet) {
                $drWant = if (('DRDirect.Lang' -as [type]) -and [DRDirect.Lang]::French) { 'fr-CA' } else { 'en-US' }   # it only accepts a full name from its own list (fr-CA, en-US...)
                $drTxt = [IO.File]::ReadAllText($drSet)
                $drNew = [regex]::Replace($drTxt, '<Language>[\s\S]*?</Language>|<Language\s*/>', '<Language>' + $drWant + '</Language>')
                if ($drNew -ne $drTxt) { [IO.File]::WriteAllText($drSet, $drNew, (New-Object Text.UTF8Encoding $true)) }
            }
        } catch { }
        $launcher = Get-DRCleanerLauncherPath
        if ($launcher) { $env:DRDIRECT_CLEANER_EXE = $launcher }
        Start-Process -FilePath $uninstaller -WorkingDirectory (Split-Path -Parent $uninstaller)
    } catch {
        [DRDirect.MsgBox]::Show("Could not open the DRDirect Uninstaller Program: $($_.Exception.Message)", 'DRDirect PC Cleaner',
            [Windows.MessageBoxButton]::OK, [Windows.MessageBoxImage]::Error) | Out-Null
    }
}
# ---------- DRDirect Clone & Backup inside the Cleaner: SmartCopy, Secure, Check, Restore, Rescue USB ----------
# Clone & Backup keeps the PC awake and at full speed while it works. Without this, an end user's PC went to
# sleep part-way through Secure (nothing is read or written while asleep) and Windows' power saving slowed the
# Cleaner down when its window was in the background, so one image took 24 hours.
function Set-DRStayAwake {
    param([bool]$On)
    try {
        if (-not ('DRDirect.StayAwake' -as [type])) {
            Add-Type -Namespace DRDirect -Name StayAwake -MemberDefinition @'
[DllImport("kernel32.dll")] public static extern uint SetThreadExecutionState(uint flags);
[DllImport("kernel32.dll")] public static extern IntPtr GetCurrentProcess();
[DllImport("kernel32.dll", SetLastError = true)] public static extern bool SetProcessInformation(IntPtr process, int infoClass, ref PowerThrottling info, int size);
[StructLayout(LayoutKind.Sequential)] public struct PowerThrottling { public uint Version; public uint ControlMask; public uint StateMask; }
public static void Throttle(bool allow)
{
    // ProcessPowerThrottling = 4; EXECUTION_SPEED = 1. Mask set with state 0 = never slow this process down;
    // mask 0 = Windows decides again, as it normally does.
    PowerThrottling p = new PowerThrottling(); p.Version = 1; p.ControlMask = allow ? 0u : 1u; p.StateMask = 0;
    SetProcessInformation(GetCurrentProcess(), 4, ref p, Marshal.SizeOf(typeof(PowerThrottling)));
}
'@ -ErrorAction Stop
        }
        # ES_CONTINUOUS | ES_SYSTEM_REQUIRED (no sleep). The screen may still turn off, which is fine.
        if ($On) { [void][DRDirect.StayAwake]::SetThreadExecutionState([uint32]2147483649); [DRDirect.StayAwake]::Throttle($false) }
        else { [void][DRDirect.StayAwake]::SetThreadExecutionState([uint32]2147483648); [DRDirect.StayAwake]::Throttle($true) }
    } catch { }
}

# Hours keep counting past 24 (hh:mm:ss would start again at 00 after a day).
function Format-DRRunTime([TimeSpan]$Span) { '{0:00}:{1:00}:{2:00}' -f [int][Math]::Floor($Span.TotalHours), $Span.Minutes, $Span.Seconds }

# True when a laptop is running on its battery (a desktop, or a laptop on the charger, gives false).
function Test-DROnBattery {
    try { return ([System.Windows.Forms.SystemInformation]::PowerStatus.PowerLineStatus -eq [System.Windows.Forms.PowerLineStatus]::Offline) } catch { return $false }
}

# The Imager engine is loaded only when this window opens, so the Cleaner starts as fast as before.
# Its functions are made script-wide so the window's click handlers can see them.
function Get-DRImagerEngineText {
    if (-not $script:DRImagerEngineCode) { return $null }
    # The engine looks for its WinPE copy beside itself; inside the Cleaner there is no such file, so point it somewhere harmless.
    $script:DRImagerEngineCode.ToString().Replace('Join-Path $PSScriptRoot ''DRImgEngine.dll''', 'Join-Path $env:SystemRoot ''DRImgEngine.dll''')
}
function Import-DRImagerEngine {
    if (('DRImgJob' -as [type]) -and (Get-Command Get-SmartExtents -ErrorAction SilentlyContinue)) { return $true }
    $code = Get-DRImagerEngineText
    if (-not $code) { return $false }
    $code = [regex]::Replace($code, '(?m)^function (?=[A-Za-z])', 'function script:')
    . ([scriptblock]::Create($code))
    return [bool](('DRImgJob' -as [type]) -and (Get-Command Get-SmartExtents -ErrorAction SilentlyContinue))
}

# Where the Rescue system (DRDirect Imager Rescue.iso, with the ADK beside it) lives on this PC, or $null.
function Resolve-DRImagerHome {
    $places = New-Object System.Collections.Generic.List[string]
    try { if ($PSScriptRoot) { $places.Add((Join-Path $PSScriptRoot 'DRDirect Imager')); $places.Add((Join-Path (Split-Path -Parent $PSScriptRoot) 'DRDirect Imager')) } } catch { }
    try { if ($env:USERPROFILE) { $places.Add((Join-Path $env:USERPROFILE 'DRDirect Imager')) } } catch { }
    foreach ($p in $places) {
        try { if (Test-Path -LiteralPath (Join-Path $p 'DRDirect Imager Rescue.iso') -PathType Leaf) { return $p } } catch { }
    }
    $null
}

# Where to copy the Rescue system from: the Rescue file (ISO), the copy the Cleaner saved on this PC, or a
# DRDirect Rescue USB that is plugged in (saved to this PC first, so the same stick can be made again). $null if none.
# Windows ignores the icon in autorun.inf on USB sticks, so a Rescue USB showed a plain drive. Windows does use
# DriveIcons in the registry, set per drive letter. Every plugged-in DRDirect Rescue USB gets the DRDirect logo and
# name; a letter we set earlier that is no longer a Rescue USB is cleared (only entries marked as ours).
function Set-DRRescueDriveIcons {
    try {
        $base = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\DriveIcons'
        $rescue = @{}
        # Bigger and faster USB sticks often tell Windows they are 'Fixed' drives, not 'Removable', so the type is
        # not used. A Rescue USB is known by its own DRDirect files: the logo and its lock file. The Windows drive never counts.
        $sysLetter = ([string]$env:SystemDrive).TrimEnd(':').ToUpperInvariant()
        foreach ($v in @(Get-Volume -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter -and [string]$_.DriveType -in @('Removable', 'Fixed') })) {
            $l = ([string]$v.DriveLetter).ToUpperInvariant()
            if ($l -eq $sysLetter) { continue }
            $ico = "$($l):\DRDirect\DRDirect.ico"
            $hasLock = (Test-Path -LiteralPath "$($l):\DRDirect\pc.id") -or (Test-Path -LiteralPath "$($l):\DRDirect\owner.id") -or (Test-Path -LiteralPath "$($l):\DRDirect\usb.id")
            if ($hasLock -and -not (Test-Path -LiteralPath $ico)) {
                # A Rescue USB made without its logo file (end-user PCs did not have it): put the DRDirect logo back.
                $from = $null
                foreach ($pl in @((Join-Path $env:LOCALAPPDATA 'DRDirect PC Cleaner\Scripts'), $(if ($PSScriptRoot) { Join-Path $PSScriptRoot 'DRDirect Imager' }), $PSScriptRoot)) {
                    if (-not $pl) { continue }
                    foreach ($n in 'DRDirect Image.ico', 'DRDirectCleaner.ico') { $c = Join-Path $pl $n; if (Test-Path -LiteralPath $c -PathType Leaf) { $from = $c; break } }
                    if ($from) { break }
                }
                if ($from) {
                    try {
                        Copy-Item -LiteralPath $from -Destination $ico -Force -ErrorAction Stop
                        $ar = "$($l):\autorun.inf"
                        if (-not (Test-Path -LiteralPath $ar)) { Set-Content -LiteralPath $ar -Value "[autorun]`r`nicon=DRDirect\DRDirect.ico`r`nlabel=DRDirect Rescue" -Encoding ASCII; try { (Get-Item -LiteralPath $ar -Force).Attributes = 'Hidden, System, Archive' } catch { } }
                    } catch { }
                }
            }
            $isRescue = (Test-Path -LiteralPath $ico) -and ((Test-Path -LiteralPath "$($l):\DRDirect\pc.id") -or (Test-Path -LiteralPath "$($l):\DRDirect\owner.id") -or (Test-Path -LiteralPath "$($l):\DRDirect\usb.id"))
            if ($isRescue) { $rescue[$l] = $ico }
        }
        foreach ($l in $rescue.Keys) {
            $k = Join-Path $base $l
            $null = New-Item -Path (Join-Path $k 'DefaultIcon') -Force
            Set-Item -Path (Join-Path $k 'DefaultIcon') -Value $rescue[$l]
            $null = New-Item -Path (Join-Path $k 'DefaultLabel') -Force
            Set-Item -Path (Join-Path $k 'DefaultLabel') -Value 'DRDirect Rescue'
            Set-ItemProperty -Path $k -Name 'DRDirectRescue' -Value 1 -Type DWord
        }
        foreach ($old in @(Get-ChildItem -Path $base -ErrorAction SilentlyContinue)) {
            $l = Split-Path -Leaf $old.PSPath
            $ours = $null; try { $ours = (Get-ItemProperty -Path $old.PSPath -Name 'DRDirectRescue' -ErrorAction Stop).DRDirectRescue } catch { }
            if ($ours -and -not $rescue.ContainsKey($l.ToUpperInvariant())) { Remove-Item -Path $old.PSPath -Recurse -Force -ErrorAction SilentlyContinue }
        }
    } catch { }
}

function Get-DRSavedRescueFolder { Join-Path $env:LOCALAPPDATA 'DRDirect PC Cleaner\Rescue System' }
# End users do not have the Rescue system on their PC, so Clone & Backup downloads it (once) when a Rescue USB is made.
# It is checked against its SHA-256 before it is used; a file that does not match is thrown away.
$script:DRRescueDownload = @{ Url = 'https://github.com/Phears/drdirect-cleaner-updates/releases/download/rescue-1/DRDirect-Rescue.iso'; Sha256 = 'BD8F3F082A32D6164A805F92EB0504A39AE2EEB19B810BA680E9723D61240463'; Size = [int64]560392192 }
function Get-DRDownloadedRescueIso { Join-Path $env:LOCALAPPDATA 'DRDirect PC Cleaner\Rescue System.iso' }
function Test-DRRescueTree { param([string]$Root) try { (Test-Path -LiteralPath (Join-Path $Root 'bootmgr')) -and (Test-Path -LiteralPath (Join-Path $Root 'sources\boot.wim')) } catch { $false } }
function Find-DRRescueSource {
    $home2 = Resolve-DRImagerHome
    if ($home2) { return (Join-Path $home2 'DRDirect Imager Rescue.iso') }
    $saved = Get-DRSavedRescueFolder
    if (Test-DRRescueTree $saved) { return $saved }
    $dl = Get-DRDownloadedRescueIso
    if ((Test-Path -LiteralPath $dl -PathType Leaf) -and (Test-Path -LiteralPath ($dl + '.ok') -PathType Leaf)) { return $dl }
    foreach ($v in @(Get-Volume -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter })) {
        $r = "$($v.DriveLetter):\"
        if (-not (Test-DRRescueTree $r)) { continue }
        # A Windows install stick has the same boot files; only a DRDirect Rescue USB is used.
        if ((Test-Path -LiteralPath (Join-Path $r 'sources\install.wim')) -or (Test-Path -LiteralPath (Join-Path $r 'sources\install.esd'))) { continue }
        $isOurs = ([string]$v.FileSystemLabel -eq 'DRDIRECT') -or (Test-Path -LiteralPath (Join-Path $r 'DRDirect'))
        if (-not $isOurs) { try { $isOurs = ([IO.File]::ReadAllText((Join-Path $r 'autorun.inf')) -match 'DRDirect') } catch { } }
        if ($isOurs) { return $r }
    }
    $null
}

# Rescue USB: only USB flash drives are ever offered, never the Windows drive or an internal drive. (Same as the Imager.)
function Get-DRRescueUsbDisks {
    foreach ($d in (Get-Disk -ErrorAction SilentlyContinue | Sort-Object Number)) {
        if ([string]$d.BusType -ne 'USB' -or $d.IsBoot -or $d.IsSystem) { continue }
        # Never a big USB hard drive or SSD (backup drives): flash drives only, so nothing over 300 GB.
        if ([int64]$d.Size -gt 300GB) { continue }
        $letters = @(Get-Partition -DiskNumber $d.Number -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter } | ForEach-Object { [string]$_.DriveLetter })
        $files = 0; $usedBytes = 0L
        foreach ($l in $letters) {
            try {
                $v = Get-Volume -DriveLetter $l -ErrorAction Stop
                $usedBytes += ($v.Size - $v.SizeRemaining)
                $files += @(Get-ChildItem -LiteralPath ("$l`:\") -Recurse -File -Force -ErrorAction SilentlyContinue).Count
            } catch { }
        }
        [pscustomobject]@{ Number = [int]$d.Number; Name = [string]$d.FriendlyName; Size = [int64]$d.Size; Letters = $letters; Files = $files; UsedBytes = $usedBytes }
    }
}

# The Imager's Rescue USB writer, run in the background so the animation keeps moving while the stick is written.
$script:DRRescueUsbWriter = @'
function Write-RescueUsb {
    param([int]$DiskNumber, [string]$IsoPath, [string]$ExpectLetter, [switch]$AllowVirtual, [string]$OwnerPassword, [scriptblock]$Say = { param($t) })
    $mounted = $false
    try {
        $disk = Get-Disk -Number $DiskNumber -ErrorAction Stop
        $okBus = ([string]$disk.BusType -eq 'USB') -or ($AllowVirtual -and [string]$disk.BusType -eq 'File Backed Virtual')
        if (-not $okBus) { return @{ Ok = $false; Message = "Disk $DiskNumber is not a USB flash drive. Nothing was changed." } }
        if ($disk.IsBoot -or $disk.IsSystem) { return @{ Ok = $false; Message = 'That is the Windows drive. Nothing was changed.' } }
        if (-not (Test-Path -LiteralPath $IsoPath)) { return @{ Ok = $false; Message = 'The rescue file is missing. Nothing was changed.' } }
        # Copying from a Rescue USB: keep its rescue system on this PC first, so the stick can be erased and made again.
        if ($IsoPath -match '^[A-Za-z]:\\$') {
            & $Say 'Saving the Rescue system to this PC...'
            $saveTo = Join-Path $env:LOCALAPPDATA 'DRDirect PC Cleaner\Rescue System'
            $null = New-Item -ItemType Directory -Force -Path $saveTo
            & robocopy.exe $IsoPath $saveTo /MIR /R:2 /W:2 /NFL /NDL /NJH /NJS /NP /XD 'System Volume Information' /XF usb.id pc.id owner.id | Out-Null
            if ($LASTEXITCODE -ge 8) { return @{ Ok = $false; Message = "The Rescue system could not be saved from the USB (robocopy code $LASTEXITCODE). Nothing was changed." } }
            if (-not ((Test-Path -LiteralPath (Join-Path $saveTo 'bootmgr')) -and (Test-Path -LiteralPath (Join-Path $saveTo 'sources\boot.wim')))) { return @{ Ok = $false; Message = 'The Rescue system on the USB is not complete. Nothing was changed.' } }
            $IsoPath = $saveTo
        }
        $fromFolder = Test-Path -LiteralPath $IsoPath -PathType Container
        if ($ExpectLetter) {
            $have = @(Get-Partition -DiskNumber $DiskNumber -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter } | ForEach-Object { [string]$_.DriveLetter })
            if ($have -notcontains $ExpectLetter.ToUpperInvariant()) { return @{ Ok = $false; Message = "Drive $($ExpectLetter): is not on disk $DiskNumber any more. Nothing was changed." } }
        }
        & $Say 'Erasing the USB flash drive...'
        Set-Disk -Number $DiskNumber -IsOffline $false -ErrorAction SilentlyContinue
        Set-Disk -Number $DiskNumber -IsReadOnly $false -ErrorAction SilentlyContinue
        # A brand-new stick can be raw (never initialized); there is nothing to clear on it.
        $disk = Get-Disk -Number $DiskNumber -ErrorAction Stop
        if ([string]$disk.PartitionStyle -ne 'RAW') { Clear-Disk -Number $DiskNumber -RemoveData -RemoveOEM -Confirm:$false -ErrorAction Stop }
        # After clearing, Windows may leave the stick already set up (empty MBR) or raw; set it up only when raw, and make sure it is MBR.
        $disk = Get-Disk -Number $DiskNumber -ErrorAction Stop
        if ([string]$disk.PartitionStyle -eq 'RAW') { Initialize-Disk -Number $DiskNumber -PartitionStyle MBR -ErrorAction Stop }
        elseif ([string]$disk.PartitionStyle -ne 'MBR') { Set-Disk -Number $DiskNumber -PartitionStyle MBR -ErrorAction Stop }
        & $Say 'Formatting...'
        # FAT32 so every PC can start from it; Windows formats FAT32 only up to 32 GB, so the first partition is capped.
        $cap = [int64]30GB
        $part = if ($disk.Size -gt $cap) { New-Partition -DiskNumber $DiskNumber -Size $cap -AssignDriveLetter -IsActive -ErrorAction Stop } else { New-Partition -DiskNumber $DiskNumber -UseMaximumSize -AssignDriveLetter -IsActive -ErrorAction Stop }
        $null = Format-Volume -Partition $part -FileSystem FAT32 -NewFileSystemLabel 'DRDIRECT' -Confirm:$false -Force -ErrorAction Stop
        $dest = ([string]$part.DriveLetter) + ':\'
        & $Say 'Copying the rescue system...'
        # No backslash at the end: with a space in the path, a final backslash makes robocopy misread the folder.
        if ($fromFolder) { $src = $IsoPath.TrimEnd('\') }
        else {
            $img = Mount-DiskImage -ImagePath $IsoPath -PassThru -ErrorAction Stop
            $mounted = $true
            $src = (($img | Get-Volume).DriveLetter) + ':\'
        }
        $rcOut = @(& robocopy.exe $src $dest /E /R:2 /W:2 /NFL /NDL /NJH /NJS /NP 2>&1 | ForEach-Object { [string]$_ } | Where-Object { $_.Trim() })
        if ($LASTEXITCODE -ge 8) { throw ("Copying failed (robocopy code $LASTEXITCODE). From: $src  To: $dest  " + (($rcOut | Select-Object -Last 3) -join ' ')) }
        if ($mounted) { Dismount-DiskImage -ImagePath $IsoPath | Out-Null; $mounted = $false }
        # Old-style PCs (BIOS) need the boot sector written too.
        $bootsect = Get-ChildItem -LiteralPath (Join-Path $PSScriptRoot 'ADK') -Recurse -Filter 'bootsect.exe' -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($bootsect) { & $bootsect.FullName /nt60 ($dest.TrimEnd('\')) /force /mbr 2>&1 | Out-Null }
        & $Say 'Setting up the stick...'
        # Boot files are hidden, so the stick looks tidy: only the DRDirect app, a launcher and a readme show.
        foreach ($item in (Get-ChildItem -LiteralPath $dest -Force -ErrorAction SilentlyContinue)) {
            try { $item.Attributes = $item.Attributes -bor [IO.FileAttributes]::Hidden -bor [IO.FileAttributes]::System } catch { }
        }
        $app = Join-Path $dest 'DRDirect'; $null = New-Item -ItemType Directory -Force -Path $app
        # The Windows app on the stick, so the same stick also works from inside Windows.
        # The app files can sit in several places (beside the Imager, in the Cleaner's own folder, or in the saved Rescue system).
        $appPlaces = @($PSScriptRoot, (Join-Path $PSScriptRoot 'DRDirect Imager'), (Join-Path $env:LOCALAPPDATA 'DRDirect PC Cleaner'),
            (Join-Path $env:LOCALAPPDATA 'DRDirect PC Cleaner\Rescue System\DRDirect'), (Join-Path $env:LOCALAPPDATA 'DRDirect PC Cleaner\Scripts'))
        $ico = $null
        foreach ($f in 'DRDirect Imager.ps1', 'DRDirect Imager Engine.ps1', 'DRDirect Image.ico', 'DRDirect Logo.png') {
            foreach ($pl in $appPlaces) {
                if (-not $pl) { continue }
                $s = Join-Path $pl $f
                if (Test-Path -LiteralPath $s -PathType Leaf) { Copy-Item -LiteralPath $s -Destination $app -Force -ErrorAction Stop; if ($f -eq 'DRDirect Image.ico') { $ico = $s }; break }
            }
        }
        if (-not (Test-Path -LiteralPath (Join-Path $app 'DRDirect Imager.ps1'))) { throw ("DRDirect Imager.ps1 was not found to put on the USB. Looked in: " + (($appPlaces | Where-Object { $_ }) -join ' | ')) }
        if (-not $ico) { $ico = Join-Path $PSScriptRoot 'DRDirect Image.ico' }
        if (-not (Test-Path -LiteralPath $ico)) {
            # End-user PCs may not have the Clone & Backup logo; the Cleaner's own DRDirect logo is always there.
            foreach ($n in 'DRDirect Image.ico', 'DRDirectCleaner.ico') {
                foreach ($pl in $appPlaces) { if ($pl) { $c = Join-Path $pl $n; if (Test-Path -LiteralPath $c -PathType Leaf) { $ico = $c; break } } }
                if (Test-Path -LiteralPath $ico) { break }
            }
        }
        if (Test-Path -LiteralPath $ico) {
            Copy-Item -LiteralPath $ico -Destination (Join-Path $app 'DRDirect.ico') -Force
            Set-Content -LiteralPath (Join-Path $dest 'autorun.inf') -Value "[autorun]`r`nicon=DRDirect\DRDirect.ico`r`nlabel=DRDirect Rescue" -Encoding ASCII
            try { (Get-Item -LiteralPath (Join-Path $dest 'autorun.inf') -Force).Attributes = 'Hidden, System, Archive' } catch { }
        }
        # Windows ignores the autorun.inf icon on USB sticks; DriveIcons in the registry is what it shows.
        # Only when the logo is really on the stick: pointing Windows at a missing file shows a blank page icon.
        if (Test-Path -LiteralPath (Join-Path $app 'DRDirect.ico')) { try {
            $dk = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\DriveIcons\' + ([string]$part.DriveLetter).ToUpperInvariant()
            $null = New-Item -Path ($dk + '\DefaultIcon') -Force; Set-Item -Path ($dk + '\DefaultIcon') -Value ((Join-Path $app 'DRDirect.ico'))
            $null = New-Item -Path ($dk + '\DefaultLabel') -Force; Set-Item -Path ($dk + '\DefaultLabel') -Value 'DRDirect Rescue'
            Set-ItemProperty -Path $dk -Name 'DRDirectRescue' -Value 1 -Type DWord
        } catch { } }
        $launcher = "@echo off`r`nstart `"`" powershell.exe -NoProfile -STA -ExecutionPolicy Bypass -WindowStyle Hidden -File `"%~dp0DRDirect\DRDirect Imager.ps1`"`r`n"
        Set-Content -LiteralPath (Join-Path $dest 'DRDirect Clone & Backup.bat') -Value $launcher -Encoding ASCII
        $readme = "Directional Aid for Users`r`n-------------------------`r`n`r`nThis is a DRDirect Rescue USB. It holds hidden boot files. Please do not change anything on it.`r`nTo start a rescue, restart the PC from this USB. To use the app inside Windows, open DRDirect Clone & Backup.bat.`r`nTo make another Rescue USB, use the Rescue USB button in DRDirect Clone & Backup. Copying these files is not enough.`r`n`r`nDRDirect`r`n"
        Set-Content -LiteralPath (Join-Path $dest 'readme.txt') -Value $readme -Encoding ASCII
        # The PC this stick was made for, kept as hashes (never the plain ID), for the PC lock.
        # The stick's own serial number, so a copy on another stick refuses to start (skipped when the stick reports none).
        $serialHash = Get-StickSerialHash ([string]$part.DriveLetter)
        if ($serialHash) { Set-Content -LiteralPath (Join-Path $app 'usb.id') -Value $serialHash -Encoding ASCII }
        if ($OwnerPassword) {
            # Master stick: no PC lock; it asks for the owner password instead.
            Set-Content -LiteralPath (Join-Path $app 'owner.id') -Value (New-OwnerRecord $OwnerPassword) -Encoding ASCII
        } else {
        try {
            $uuid = ([string](Get-CimInstance Win32_ComputerSystemProduct).UUID).Trim()
            $serial = ([string](Get-CimInstance Win32_BaseBoard).SerialNumber).Trim()
            $ids = @(); if ($uuid) { $ids += $uuid.ToLowerInvariant() }; if ($uuid -and $serial) { $ids += ("{0}-{1}" -f $uuid, $serial).ToLowerInvariant() }
            $hashes = foreach ($id in $ids) { ([Security.Cryptography.SHA256]::Create().ComputeHash([Text.Encoding]::UTF8.GetBytes($id)) | ForEach-Object { $_.ToString('X2') }) -join '' }
            Set-Content -LiteralPath (Join-Path $app 'pc.id') -Value $hashes -Encoding ASCII
        } catch { }
        }
        # Lock files are hidden and read-only so they are not changed by accident.
        foreach ($lf in 'pc.id', 'owner.id', 'usb.id') { $lp = Join-Path $app $lf; if (Test-Path -LiteralPath $lp) { try { (Get-Item -LiteralPath $lp -Force).Attributes = 'Hidden, ReadOnly, Archive' } catch { } } }
        & $Say 'Checking...'
        foreach ($need in 'bootmgr', 'EFI\Boot\bootx64.efi', 'sources\boot.wim', $(if ($OwnerPassword) { 'DRDirect\owner.id' } else { 'DRDirect\pc.id' }), 'DRDirect\DRDirect Imager.ps1', 'readme.txt') {
            if (-not (Test-Path -LiteralPath (Join-Path $dest $need))) { throw "The check failed: $need is missing on the USB." }
        }
        return @{ Ok = $true; Message = "The Rescue USB is ready on drive $($dest.Substring(0,2))." ; Letter = $dest.Substring(0,2) }
    } catch {
        return @{ Ok = $false; Message = "It did not finish: $($_.Exception.Message)" }
    } finally {
        if ($mounted) { try { Dismount-DiskImage -ImagePath $IsoPath | Out-Null } catch { } }
    }
}

# Windows install or repair on the same Rescue USB, from a Windows ISO. The Rescue system stays exactly as it is and
# still starts first; Microsoft's Windows Setup gets its own start-up menu entry, and the Rescue screen shows a
# Windows repair button for it. FAT32 holds files up to 4 GB, so a bigger Windows image is split into parts Setup reads.
function Add-DRWindowsSetup {
    param([string]$Root, [string]$WinIso, [scriptblock]$Say = { param($t) })
    $mounted = $false
    $tempWim = Join-Path $env:TEMP 'DRDirect-install-export.wim'
    try {
        if (-not (Test-Path -LiteralPath $WinIso -PathType Leaf)) { return @{ Ok = $false; Message = 'The Windows ISO file was not found.' } }
        & $Say 'Opening the Windows ISO...'
        $img = Mount-DiskImage -ImagePath $WinIso -PassThru -ErrorAction Stop; $mounted = $true
        $iso = (($img | Get-Volume).DriveLetter) + ':\'
        foreach ($need in 'setup.exe', 'sources\boot.wim') { if (-not (Test-Path -LiteralPath ($iso + $need))) { return @{ Ok = $false; Message = 'That ISO is not a Windows install ISO.' } } }
        $install = @('sources\install.wim', 'sources\install.esd') | ForEach-Object { $iso + $_ } | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
        if (-not $install) { return @{ Ok = $false; Message = 'That ISO has no Windows image in it.' } }
        $wi = Get-WindowsImage -ImagePath $install -Index 1
        $isoBuild = [int]([version]$wi.Version).Build
        if ([int]$wi.Architecture -ne 9) { return @{ Ok = $false; Message = 'That ISO is not for 64-bit Intel and AMD PCs.' } }
        $pcBuild = [Environment]::OSVersion.Version.Build
        $isoName = if ($isoBuild -ge 22000) { 'Windows 11' } else { 'Windows 10' }
        $pcName = if ($pcBuild -ge 22000) { 'Windows 11' } else { 'Windows 10' }
        if ($isoName -ne $pcName) { return @{ Ok = $false; Message = "That ISO is $isoName, but this PC has $pcName. Use a $pcName ISO." } }
        $vol = Get-Volume -DriveLetter $Root.Substring(0, 1)
        $need = [int64](Get-ChildItem -LiteralPath $iso -Recurse -File -Force | Measure-Object Length -Sum).Sum + 300MB
        if ($vol.SizeRemaining -lt $need) { return @{ Ok = $false; Message = ('Not enough room on the USB for Windows: it needs {0:N1} GB and has {1:N1} GB. Use a USB of 16 GB or more.' -f ($need / 1e9), ($vol.SizeRemaining / 1e9)) } }
        & $Say "Copying $isoName Setup..."
        & robocopy.exe $iso.TrimEnd('\') $Root.TrimEnd('\') /E /R:2 /W:2 /NFL /NDL /NJH /NJS /NP /XD (Join-Path $iso 'boot') (Join-Path $iso 'efi') /XF bootmgr bootmgr.efi autorun.inf boot.wim install.wim install.esd | Out-Null
        if ($LASTEXITCODE -ge 8) { return @{ Ok = $false; Message = "Copying Windows Setup failed (robocopy code $LASTEXITCODE)." } }
        Copy-Item -LiteralPath ($iso + 'sources\boot.wim') -Destination ($Root + 'sources\winsetup.wim') -Force
        (Get-Item -LiteralPath ($Root + 'sources\winsetup.wim')).IsReadOnly = $false
        $limit = [int64]4294967295
        $instItem = Get-Item -LiteralPath $install
        if ($instItem.Length -lt $limit) {
            & $Say "Copying $isoName (this takes a while)..."
            Copy-Item -LiteralPath $install -Destination ($Root + 'sources\' + $instItem.Name) -Force
        } else {
            $splitFrom = $install
            if ($instItem.Extension -eq '.esd') {
                & $Say "Preparing $isoName (this takes a while)..."
                Remove-Item -LiteralPath $tempWim -ErrorAction SilentlyContinue
                foreach ($i in @(Get-WindowsImage -ImagePath $install)) {
                    & dism.exe /Export-Image "/SourceImageFile:$install" "/SourceIndex:$($i.ImageIndex)" "/DestinationImageFile:$tempWim" /Compress:max /CheckIntegrity | Out-Null
                    if ($LASTEXITCODE -ne 0) { return @{ Ok = $false; Message = "Windows could not be prepared (DISM code $LASTEXITCODE)." } }
                }
                $splitFrom = $tempWim
            }
            & $Say "Copying $isoName in parts (this takes a while)..."
            $swm = $Root + 'sources\install.swm'
            & dism.exe /Split-Image "/ImageFile:$splitFrom" "/SWMFile:$swm" /FileSize:3800 /CheckIntegrity | Out-Null
            if ($LASTEXITCODE -ne 0) { return @{ Ok = $false; Message = "Windows could not be copied in parts (DISM code $LASTEXITCODE)." } }
        }
        & $Say 'Adding Windows install or repair to the start-up menu...'
        $ids = [ordered]@{}
        foreach ($k in 'BIOS', 'EFI') {
            $s = if ($k -eq 'BIOS') { $Root + 'Boot\BCD' } else { $Root + 'EFI\Microsoft\Boot\BCD' }
            if (-not (Test-Path -LiteralPath $s)) { continue }
            (Get-Item -LiteralPath $s -Force).Attributes = 'Archive'
            $def = (& bcdedit.exe /store $s /enum '{default}') -join "`n"
            $m = [regex]::Match($def, 'ramdisk=\[boot\]\\sources\\boot\.wim,(\{[0-9a-fA-F-]{36}\})')
            if (-not $m.Success) { return @{ Ok = $false; Message = "The $k start-up menu of the Rescue USB is not the usual one." } }
            $opt = $m.Groups[1].Value
            $g = [regex]::Match(((& bcdedit.exe /store $s /copy '{default}' /d 'Windows install or repair') -join ' '), '\{[0-9a-fA-F-]{36}\}')
            if (-not $g.Success) { return @{ Ok = $false; Message = "Could not add Windows to the $k start-up menu." } }
            & bcdedit.exe /store $s /set $g.Value device "ramdisk=[boot]\sources\winsetup.wim,$opt" | Out-Null
            & bcdedit.exe /store $s /set $g.Value osdevice "ramdisk=[boot]\sources\winsetup.wim,$opt" | Out-Null
            & bcdedit.exe /store $s /displayorder $g.Value /addlast | Out-Null
            & bcdedit.exe /store $s /set '{default}' description 'DRDirect Rescue' | Out-Null
            & bcdedit.exe /store $s /timeout 5 | Out-Null
            (Get-Item -LiteralPath $s -Force).Attributes = 'Hidden, System, Archive'
            $ids[$k] = $g.Value
        }
        if (-not $ids.Count) { return @{ Ok = $false; Message = 'The Rescue USB has no start-up menu to add Windows to.' } }
        Set-Content -LiteralPath ($Root + 'DRDirect\winsetup.id') -Value (($ids.Keys | ForEach-Object { "$_ $($ids[$_])" }) -join "`r`n") -Encoding ASCII
        Set-Content -LiteralPath ($Root + 'DRDirect\winsetup.txt') -Value "$isoName build $isoBuild`r`nFrom: $(Split-Path -Leaf $WinIso)`r`nAdded: $(Get-Date -Format 'yyyy-MM-dd HH:mm')" -Encoding ASCII
        foreach ($o in 'setup.exe', 'support', 'sources', 'bootmgfw.efi') { $p = $Root + $o; if (Test-Path -LiteralPath $p) { try { $it = Get-Item -LiteralPath $p -Force; $it.Attributes = $it.Attributes -bor [IO.FileAttributes]::Hidden -bor [IO.FileAttributes]::System } catch { } } }
        return @{ Ok = $true; Message = "$isoName install or repair is on the USB too." }
    } catch {
        return @{ Ok = $false; Message = $_.Exception.Message }
    } finally {
        if ($mounted) { try { Dismount-DiskImage -ImagePath $WinIso | Out-Null } catch { } }
        Remove-Item -LiteralPath $tempWim -ErrorAction SilentlyContinue
    }
}
'@

# Runs in the Rescue USB job before the writer: when this PC has no Rescue system, it is downloaded (with the
# percentage shown), checked against its SHA-256 and kept for next time.
$script:DRRescueDownloader = @'
if (-not $IsoPath) {
    $sync.Step = 'Downloading the Rescue system...'; $sync.N = $sync.N + 1
    [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    $part = $DlTo + '.part'
    $dir = Split-Path -Parent $DlTo
    $null = New-Item -ItemType Directory -Force -Path $dir
    $req = [Net.HttpWebRequest]::Create($DlUrl)
    $req.UserAgent = 'DRDirect PC Cleaner'
    $req.Timeout = 60000; $req.ReadWriteTimeout = 120000
    $resp = $req.GetResponse()
    $total = [int64]$resp.ContentLength
    $in = $resp.GetResponseStream()
    $out = [IO.File]::Create($part)
    try {
        $buf = New-Object byte[] (1MB)
        $got = [int64]0; $lastPct = -1
        while (($n = $in.Read($buf, 0, $buf.Length)) -gt 0) {
            $out.Write($buf, 0, $n); $got += $n
            if ($total -gt 0) {
                $pct = [int](100 * $got / $total)
                if ($pct -ne $lastPct) { $lastPct = $pct; $sync.Step = ('Downloading the Rescue system... {0}%  ({1:N0} of {2:N0} MB)' -f $pct, ($got / 1MB), ($total / 1MB)) }
            }
        }
    } finally { $out.Close(); $in.Close(); $resp.Close() }
    $sync.Step = 'Checking the download...'
    $h = (Get-FileHash -LiteralPath $part -Algorithm SHA256).Hash
    if ($h -ne $DlSha) { Remove-Item -LiteralPath $part -Force -ErrorAction SilentlyContinue; throw 'The download was not complete or was changed on the way. Nothing was changed on the USB. Please try again.' }
    Move-Item -LiteralPath $part -Destination $DlTo -Force
    Set-Content -LiteralPath ($DlTo + '.ok') -Value $h -Encoding ASCII
    $IsoPath = $DlTo
}
'@

# The Rescue system is made on this PC from Microsoft's own free downloads (the Windows ADK Deployment Tools and its
# Windows PE add-on), the same recipe as DRDirect's Build Rescue: Windows PE with PowerShell and .NET, plus the DRDirect
# Rescue app. DRDirect never sends Microsoft's files; only DRDirect's own app files come from the update feed.
# Microsoft's installers are downloaded from Microsoft, only run when Windows confirms Microsoft signed them, and
# show Microsoft's own screens and licence terms.
$script:DRRescueBuilder = @'
if (-not $IsoPath) {
    function Say-Build([string]$t) { $sync.Step = $t; $sync.N = $sync.N + 1 }
    $kitsKey = 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows Kits\Installed Roots'
    function Get-AdkRoot { try { $k = [string](Get-ItemProperty -LiteralPath $kitsKey -Name KitsRoot10 -ErrorAction Stop).KitsRoot10; if ($k) { return (Join-Path $k 'Assessment and Deployment Kit') } } catch { }; '' }
    function Get-MsInstaller([string]$Url, [string]$Name) {
        $f = Join-Path $env:TEMP $Name
        Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue
        [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
        $wc = New-Object Net.WebClient
        try { $wc.DownloadFile($Url, $f) } finally { $wc.Dispose() }
        $sig = Get-AuthenticodeSignature -LiteralPath $f
        if ([string]$sig.Status -ne 'Valid' -or -not $sig.SignerCertificate -or ([string]$sig.SignerCertificate.Subject -notmatch '(^|,\s*)O=Microsoft Corporation(,|$)')) {
            Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue
            throw "$Name could not be confirmed as Microsoft's, so it was not run. Nothing was changed on the USB."
        }
        $f
    }
    $adk = Get-AdkRoot
    $setEnv = if ($adk) { Join-Path $adk 'Deployment Tools\DandISetEnv.bat' } else { '' }
    if (-not $setEnv -or -not (Test-Path -LiteralPath $setEnv)) {
        Say-Build "Getting Microsoft's Windows ADK. Microsoft's installer opens - follow it (keep Deployment Tools ticked)."
        $f = Get-MsInstaller 'https://go.microsoft.com/fwlink/?linkid=2289980' 'adksetup.exe'
        $null = Start-Process -FilePath $f -ArgumentList '/features', 'OptionId.DeploymentTools', '/ceip', 'off', '/norestart' -Wait -PassThru
        Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue
        $adk = Get-AdkRoot
        $setEnv = if ($adk) { Join-Path $adk 'Deployment Tools\DandISetEnv.bat' } else { '' }
        if (-not $setEnv -or -not (Test-Path -LiteralPath $setEnv)) { throw "Microsoft's Windows ADK (Deployment Tools) was not installed, so the Rescue system could not be made. Nothing was changed on the USB." }
    }
    $peRoot = Join-Path $adk 'Windows Preinstallation Environment'
    if (-not (Test-Path -LiteralPath (Join-Path $peRoot 'amd64\en-us\winpe.wim'))) {
        Say-Build "Getting Microsoft's Windows PE add-on. Microsoft's installer opens - follow it."
        $f = Get-MsInstaller 'https://go.microsoft.com/fwlink/?linkid=2289981' 'adkwinpesetup.exe'
        $null = Start-Process -FilePath $f -ArgumentList '/features', 'OptionId.WindowsPreinstallationEnvironment', '/ceip', 'off', '/norestart' -Wait -PassThru
        Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue
        if (-not (Test-Path -LiteralPath (Join-Path $peRoot 'amd64\en-us\winpe.wim'))) { throw "Microsoft's Windows PE add-on was not installed, so the Rescue system could not be made. Nothing was changed on the USB." }
    }

    # DRDirect's own Rescue app files, from the Cleaner's folders.
    $app = @{}
    foreach ($want in @(@('DRDirect Imager Engine.ps1', 'DRDirect Imager Engine.ps1'), @('Rescue.ps1', 'DRDirect Rescue.ps1'), @('Rescue.ps1', 'Rescue.ps1'), @('DRDirect Imager.ps1', 'DRDirect Imager.ps1'), @('DRDirect Logo.png', 'DRDirect Logo.png'))) {
        if ($app.ContainsKey($want[0])) { continue }
        foreach ($dir in $AppDirs) { if ($dir) { $s = Join-Path $dir $want[1]; if (Test-Path -LiteralPath $s -PathType Leaf) { $app[$want[0]] = $s; break } } }
    }
    foreach ($must in 'DRDirect Imager Engine.ps1', 'Rescue.ps1') { if (-not $app.ContainsKey($must)) { throw "The Rescue app file '$must' is missing on this PC. Check for updates in the Cleaner, then try again. Nothing was changed on the USB." } }

    $dism = Join-Path $env:WINDIR 'System32\dism.exe'
    $work = 'C:\DRRescueBuild'          # short path with no spaces: DISM refuses long ones
    $mount = Join-Path $work 'mount'
    $ocsShort = 'C:\DRRescueOCs'
    function Run-Dism { & $dism @args | Out-Null; if ($LASTEXITCODE -ne 0) { throw "Making the Rescue system failed (DISM code $LASTEXITCODE). Nothing was changed on the USB." } }
    & $dism /Cleanup-Mountpoints | Out-Null
    if (Test-Path -LiteralPath $work) { & $dism /Unmount-Image "/MountDir:$mount" /Discard | Out-Null; Remove-Item -LiteralPath $work -Recurse -Force }

    Say-Build 'Making the Rescue system: the base...'
    $null = cmd /c "`"$setEnv`" && copype amd64 `"$work`"" 2>&1
    $wim = Join-Path $work 'media\sources\boot.wim'
    if (-not (Test-Path -LiteralPath $wim)) { throw 'Making the Rescue system failed (copype). Nothing was changed on the USB.' }
    $null = New-Item -ItemType Directory -Force -Path $mount
    Run-Dism /Mount-Image "/ImageFile:$wim" /Index:1 "/MountDir:$mount"
    $committed = $false
    try {
        if (Test-Path -LiteralPath $ocsShort) { Remove-Item -LiteralPath $ocsShort -Recurse -Force }
        Copy-Item -LiteralPath (Join-Path $peRoot 'amd64\WinPE_OCs') -Destination $ocsShort -Recurse
        foreach ($pkg in 'WinPE-WMI', 'WinPE-NetFx', 'WinPE-Scripting', 'WinPE-PowerShell', 'WinPE-StorageWMI', 'WinPE-DismCmdlets') {
            Say-Build "Making the Rescue system: adding $($pkg.Substring(6))..."
            Run-Dism "/Image:$mount" /Add-Package "/PackagePath:$(Join-Path $ocsShort "$pkg.cab")"
            $lang = Join-Path $ocsShort "en-us\${pkg}_en-us.cab"
            if (Test-Path -LiteralPath $lang) { Run-Dism "/Image:$mount" /Add-Package "/PackagePath:$lang" }
        }
        Say-Build 'Making the Rescue system: adding the DRDirect Rescue app...'
        $dst = Join-Path $mount 'Imager'
        $null = New-Item -ItemType Directory -Force -Path $dst
        foreach ($k in $app.Keys) { Copy-Item -LiteralPath $app[$k] -Destination (Join-Path $dst $k) -Force }
        # The fast engine, compiled now so the Rescue system needs no compiler (in its own process, so nothing clashes here).
        $text = [IO.File]::ReadAllText($app['DRDirect Imager Engine.ps1'])
        $m = [regex]::Match($text, "(?s)\`$script:DRImgSource = @'\r?\n(.*?)\r?\n'@")
        if (-not $m.Success) { $s0 = $text.IndexOf("@'") + 2; $e0 = $text.IndexOf("'@", $s0); $csharp = $text.Substring($s0, $e0 - $s0) } else { $csharp = $m.Groups[1].Value }
        $srcFile = Join-Path $env:TEMP 'DRImgEngine-src.cs'
        [IO.File]::WriteAllText($srcFile, $csharp)
        $dll = Join-Path $dst 'DRImgEngine.dll'
        & powershell.exe -NoProfile -Command "Add-Type -Language CSharp -TypeDefinition ([IO.File]::ReadAllText('$srcFile')) -OutputAssembly '$dll' -OutputType Library" | Out-Null
        Remove-Item -LiteralPath $srcFile -Force -ErrorAction SilentlyContinue
        if (-not (Test-Path -LiteralPath $dll)) { throw 'The fast engine could not be prepared for the Rescue system. Nothing was changed on the USB.' }
        Set-Content -LiteralPath (Join-Path $mount 'Windows\System32\startnet.cmd') -Encoding ASCII -Value "wpeinit`r`npowershell -NoProfile -ExecutionPolicy Bypass -File X:\Imager\Rescue.ps1"
        try { Run-Dism "/Image:$mount" "/Set-TimeZone:$((Get-TimeZone).Id)" } catch { }
        Say-Build 'Making the Rescue system: saving it...'
        Run-Dism /Unmount-Image "/MountDir:$mount" /Commit
        $committed = $true
    } finally {
        if (-not $committed) { & $dism /Unmount-Image "/MountDir:$mount" /Discard | Out-Null }
        Remove-Item -LiteralPath $ocsShort -Recurse -Force -ErrorAction SilentlyContinue
    }
    # Kept on this PC, so the next Rescue USB is made straight away.
    if (Test-Path -LiteralPath $SavedRescue) { Remove-Item -LiteralPath $SavedRescue -Recurse -Force }
    $null = New-Item -ItemType Directory -Force -Path (Split-Path -Parent $SavedRescue)
    Move-Item -LiteralPath (Join-Path $work 'media') -Destination $SavedRescue
    Remove-Item -LiteralPath $work -Recurse -Force -ErrorAction SilentlyContinue
    $IsoPath = $SavedRescue
}
'@

# When the last Rescue USB was made on this PC, so a lost or broken one is easy to replace.
function Get-DRRescueUsbRecord {
    try {
        $v = (Get-ItemProperty -LiteralPath 'HKCU:\Software\DRDirect\PC Cleaner' -Name 'RescueUsbLast' -ErrorAction Stop).RescueUsbLast
        $p = ([string]$v) -split '\|'
        if ($p.Count -ge 2) { return [pscustomobject]@{ When = [datetime]::ParseExact($p[0], 'yyyy-MM-dd HH:mm', [Globalization.CultureInfo]::InvariantCulture); What = $p[1] } }
    } catch { }
    $null
}
function Set-DRRescueUsbRecord([string]$What) {
    try {
        $key = 'HKCU:\Software\DRDirect\PC Cleaner'
        if (-not (Test-Path -LiteralPath $key)) { New-Item -Path $key -Force | Out-Null }
        Set-ItemProperty -LiteralPath $key -Name 'RescueUsbLast' -Value ((Get-Date).ToString('yyyy-MM-dd HH:mm', [Globalization.CultureInfo]::InvariantCulture) + '|' + ($What -replace '\|', ' ')) -Type String
    } catch { }
}

# The last backup file made with Secure, so Check, Restore and Browse start there instead of wherever Windows last was.
function Get-DRLastBackupStore {
    # Shared by every account on this PC: an elevated Cleaner can run under a hidden admin account with its own registry.
    $root = $env:ProgramData; if (-not $root) { $root = 'C:\ProgramData' }
    Join-Path $root 'DRDirect PC Cleaner\Clone and Backup - last backup.txt'
}
function Get-DRLastBackupFile {
    try {
        $f = Get-DRLastBackupStore
        if (Test-Path -LiteralPath $f -PathType Leaf) {
            $p = ([IO.File]::ReadAllText($f)).Trim()
            if ($p) { return $p }
        }
    } catch { }
    try {
        $p = [string](Get-ItemProperty -LiteralPath 'HKCU:\Software\DRDirect\PC Cleaner' -Name 'LastBackupFile' -ErrorAction Stop).LastBackupFile
        if ($p) { return $p }
    } catch { }
    $null
}
function Set-DRLastBackupFile([string]$Path) {
    if (-not $Path) { return }
    try {
        $f = Get-DRLastBackupStore
        $d = Split-Path -Parent $f
        if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Path $d -Force | Out-Null }
        [IO.File]::WriteAllText($f, $Path, (New-Object Text.UTF8Encoding($false)))
    } catch { }
    try {
        $key = 'HKCU:\Software\DRDirect\PC Cleaner'
        if (-not (Test-Path -LiteralPath $key)) { New-Item -Path $key -Force | Out-Null }
        Set-ItemProperty -LiteralPath $key -Name 'LastBackupFile' -Value $Path -Type String
    } catch { }
}
function Get-DRLastBackupFolder {
    $p = Get-DRLastBackupFile
    if ($p) { try { $d = [IO.Path]::GetDirectoryName($p); if ($d -and (Test-Path -LiteralPath $d -PathType Container)) { return $d } } catch { } }
    $null
}

# Picks where a backup goes, so nobody has to choose: the last backup folder if it is still there and on another drive,
# otherwise a 'DRDirect Backups' folder on the drive with the most free space that is not the drive being saved.
# FAT32 drives are skipped (a file there cannot be bigger than 4 GB). Returns @{ Path; Free; Letter } or $null.
function Get-DRAutoBackupPlace($Disk) {
    $skip = @(Get-DiskLetters $Disk.Number | ForEach-Object { ([string]$_).ToUpperInvariant() })
    $name = '{0} {1} drive backup.drimg' -f (Get-Date -Format 'yyyy-MM-dd'), $(if ($Disk.Letters) { ($Disk.Letters -split ' ')[0].TrimEnd(':') } else { "Disk $($Disk.Number)" })
    $folder = $null; $free = 0; $letter = $null
    $last = Get-DRLastBackupFolder
    if ($last) {
        try {
            $l = ([IO.Path]::GetPathRoot($last)).Substring(0, 1).ToUpperInvariant()
            $v = Get-Volume -DriveLetter $l -ErrorAction Stop
            if ($skip -notcontains $l -and [string]$v.FileSystem -ne 'FAT32' -and [string]$v.FileSystemLabel -ne 'DRDIRECT') { $folder = $last; $free = [double]$v.SizeRemaining; $letter = $l }
        } catch { }
    }
    if (-not $folder) {
        $best = Get-Volume -ErrorAction SilentlyContinue | Where-Object {
            $_.DriveLetter -and ($_.DriveType -eq 'Fixed' -or $_.DriveType -eq 'Removable') -and
            @('NTFS', 'exFAT', 'ReFS') -contains [string]$_.FileSystem -and $_.Size -gt 16GB -and
            [string]$_.FileSystemLabel -ne 'DRDIRECT' -and -not (Test-Path -LiteralPath "$($_.DriveLetter):\DRDirect\DRDirect Imager.ps1") -and
            $skip -notcontains ([string]$_.DriveLetter).ToUpperInvariant()
        } | Sort-Object SizeRemaining -Descending | Select-Object -First 1
        if (-not $best) { return $null }
        $letter = ([string]$best.DriveLetter).ToUpperInvariant()
        $folder = "$($letter):\DRDirect Backups"; $free = [double]$best.SizeRemaining
    }
    $path = Join-Path $folder $name
    $n = 2
    while (Test-Path -LiteralPath $path) { $path = Join-Path $folder ($name -replace '\.drimg$', " ($n).drimg"); $n++ }
    @{ Path = $path; Free = $free; Letter = $letter }
}

function Show-DRDriveCopy {
    param([string]$Mode = '')
    if ($script:activePowerShell) {
        [DRDirect.MsgBox]::Show('Please wait until the cleaning is finished, then open Clone & Backup.', 'DRDirect PC Cleaner',
            [Windows.MessageBoxButton]::OK, [Windows.MessageBoxImage]::Information) | Out-Null
        return
    }
    $window.Cursor = [Windows.Input.Cursors]::Wait
    $loaded = $false; $loadErr = $null
    try { $loaded = Import-DRImagerEngine } catch { $loadErr = $_.Exception.Message }
    if (-not $loaded -and -not $script:DRImagerEngineCode) {
        # A PC that updated with an older updater got this window but not its engine. Fetch it now.
        try {
            if ((Get-Command Repair-DRSkippedUpdateFile -ErrorAction SilentlyContinue) -and
                (Repair-DRSkippedUpdateFile -Name 'DRDirect Imager Engine.ps1')) {
                $engineFile = Join-Path (Join-Path $env:LOCALAPPDATA 'DRDirect PC Cleaner\Scripts') 'DRDirect Imager Engine.ps1'
                $script:DRImagerEngineCode = [scriptblock]::Create([IO.File]::ReadAllText($engineFile))
                $loadErr = $null
                $loaded = Import-DRImagerEngine
            }
        } catch { $loadErr = $_.Exception.Message }
    }
    $window.Cursor = $null
    # Plugged-in Rescue USBs show the DRDirect logo in File Explorer.
    Set-DRRescueDriveIcons
    if (-not $loaded) {
        $why = if ($loadErr) { "`n`n($loadErr)" } else { '' }
        [DRDirect.MsgBox]::Show("Clone & Backup is not included in this copy of the Cleaner.`nAsk DRDirect for a new build.$why", 'DRDirect PC Cleaner',
            [Windows.MessageBoxButton]::OK, [Windows.MessageBoxImage]::Information) | Out-Null
        return
    }

    [xml]$xaml = @'
