# ---------- Windows install USB: Microsoft's own Media Creation Tool ----------
# The Cleaner only checks that a big enough USB stick is plugged in, asks first, then fetches Microsoft's
# Media Creation Tool from Microsoft and opens it. Microsoft's tool makes the USB; the Cleaner never writes
# to the stick. The tool is not ours to ship, so it is downloaded from Microsoft only when this button is
# used, and it is only opened when Windows confirms Microsoft signed it. Nothing is sent anywhere.
$script:DRWinUsbMinBytes = [int64]7000000000   # Microsoft asks for "at least 8 GB"; an 8 GB stick holds a little under 8,000,000,000 bytes
$script:DRWinUsbToolUrl = 'https://go.microsoft.com/fwlink/?linkid=2156295'
$script:DRWinUsbPageUrl = 'https://www.microsoft.com/software-download/windows11'
$script:DRWinUsbPs = $null; $script:DRWinUsbAsync = $null; $script:DRWinUsbTimer = $null

function Get-DRWinUsbSticks {
    # USB flash drives only - never the Windows drive or an internal drive.
    $found = @()
    try {
        foreach ($d in @(Get-Disk -ErrorAction Stop | Sort-Object Number)) {
            if ([string]$d.BusType -ne 'USB' -or $d.IsBoot -or $d.IsSystem) { continue }
            # Never a big USB hard drive or SSD (backup drives): flash drives only, so nothing over 300 GB.
            if ([int64]$d.Size -gt 300GB) { continue }
            $letters = @(Get-Partition -DiskNumber $d.Number -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter } | ForEach-Object { [string]$_.DriveLetter + ':' })
            $found += [pscustomobject]@{ Name = ([string]$d.FriendlyName).Trim(); Size = [int64]$d.Size; Letters = ($letters -join ' ') }
        }
        return $found
    } catch { }
    # Without administrator rights Get-Disk can be refused; Windows' own drive list still names USB sticks.
    foreach ($d in @(Get-CimInstance Win32_DiskDrive -Filter "InterfaceType='USB'" -ErrorAction SilentlyContinue)) {
        $found += [pscustomobject]@{ Name = ([string]$d.Model).Trim(); Size = [int64]$d.Size; Letters = '' }
    }
    $found
}

function Format-DRWinUsbSize([int64]$Bytes) { '{0:N1} GB' -f ($Bytes / 1e9) }

function Open-DRWinUsbPage {
    try { Start-Process $script:DRWinUsbPageUrl | Out-Null } catch { }
}

function Start-DRWindowsInstallUsb {
    if ($script:DRWinUsbPs) {
        [DRDirect.MsgBox]::Show("Microsoft's Media Creation Tool is still downloading. It opens by itself when it is ready.", 'DRDirect PC Cleaner') | Out-Null
        return
    }
    if ($env:PROCESSOR_ARCHITECTURE -eq 'ARM64' -or -not [Environment]::Is64BitOperatingSystem) {
        [DRDirect.MsgBox]::Show("Microsoft's Media Creation Tool only makes Windows 11 USBs for 64-bit Intel and AMD PCs, and this PC is not one.`n`nNothing was changed.", 'DRDirect PC Cleaner', 'OK', 'Information') | Out-Null
        return
    }
    $sticks = @(Get-DRWinUsbSticks)
    $big = @($sticks | Where-Object { $_.Size -ge $script:DRWinUsbMinBytes })
    if ($big.Count -eq 0) {
        $msg = "Plug in a USB stick of at least 8 GB, then press Windows install USB again.`n`n"
        if ($sticks.Count) {
            $msg += "Too small:`n" + (($sticks | ForEach-Object { '  - {0}  ({1})' -f $_.Name, (Format-DRWinUsbSize $_.Size) }) -join "`n") + "`n`n"
        } else {
            $msg += "No USB stick was found.`n`n"
        }
        $msg += 'Nothing was changed.'
        [DRDirect.MsgBox]::Show($msg, 'DRDirect PC Cleaner - Windows install USB', 'OK', 'Warning') | Out-Null
        return
    }
    $list = ($big | ForEach-Object { '  - {0}  {1}  ({2})' -f $_.Name, $_.Letters, (Format-DRWinUsbSize $_.Size) }) -join "`n"
    $question = "Make a Windows 11 install USB?`n`n" +
        "USB stick(s) big enough (8 GB or more):`n$list`n`n" +
        "Microsoft's Media Creation Tool will be downloaded from Microsoft and opened. In it:`n" +
        "  1. Accept Microsoft's licence terms.`n" +
        "  2. Choose USB flash drive.`n" +
        "  3. Pick your USB stick.`n`n" +
        "EVERYTHING on the USB stick you pick will be erased.`n" +
        "Microsoft's tool then downloads Windows, so it needs the internet.`n`n" +
        "Continue?"
    $answer = [DRDirect.MsgBox]::Show($question, 'DRDirect PC Cleaner - Windows install USB', 'YesNo', 'Question')
    if ($answer -ne 'Yes') { return }

    $folder = Join-Path $env:LOCALAPPDATA 'DRDirect PC Cleaner\Windows USB'
    $file = Join-Path $folder 'MediaCreationTool.exe'
    try { $null = New-Item -ItemType Directory -Force -Path $folder } catch { }
    $ui.NavWinUsb.IsEnabled = $false
    $ui.NavWinUsb.Content = '⛨   Downloading the tool...'

    # Downloaded in the background so the window keeps working. A fresh copy each time, so it is always Microsoft's latest.
    $script:DRWinUsbPs = [PowerShell]::Create()
    [void]$script:DRWinUsbPs.AddScript({
        param($Url, $File)
        try {
            [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
            if (Test-Path -LiteralPath $File) { Remove-Item -LiteralPath $File -Force -ErrorAction Stop }
            $part = $File + '.part'
            if (Test-Path -LiteralPath $part) { Remove-Item -LiteralPath $part -Force -ErrorAction Stop }
            $wc = New-Object Net.WebClient
            try { $wc.DownloadFile($Url, $part) } finally { $wc.Dispose() }
            Move-Item -LiteralPath $part -Destination $File -Force
            ''
        } catch { $_.Exception.Message }
    }).AddArgument($script:DRWinUsbToolUrl).AddArgument($file)
    $script:DRWinUsbAsync = $script:DRWinUsbPs.BeginInvoke()
    $script:DRWinUsbFile = $file
    $script:DRWinUsbTimer = New-Object Windows.Threading.DispatcherTimer
    $script:DRWinUsbTimer.Interval = [TimeSpan]::FromMilliseconds(400)
    $script:DRWinUsbTimer.Add_Tick({
        if (-not $script:DRWinUsbAsync.IsCompleted) { return }
        $script:DRWinUsbTimer.Stop()
        $err = ''
        try { $err = [string](@($script:DRWinUsbPs.EndInvoke($script:DRWinUsbAsync)) -join '') } catch { $err = $_.Exception.Message }
        try { $script:DRWinUsbPs.Dispose() } catch { }
        $script:DRWinUsbPs = $null; $script:DRWinUsbAsync = $null
        $ui.NavWinUsb.IsEnabled = $true
        $ui.NavWinUsb.Content = '⛨   Windows repair USB'
        $file = $script:DRWinUsbFile
        $title = 'DRDirect PC Cleaner - Windows install USB'
        if ($err -or -not (Test-Path -LiteralPath $file)) {
            $a = [DRDirect.MsgBox]::Show("Microsoft's Media Creation Tool could not be downloaded.`n$err`n`nNothing was changed. Open Microsoft's Windows 11 download page instead?", $title, 'YesNo', 'Warning')
            if ($a -eq 'Yes') { Open-DRWinUsbPage }
            return
        }
        # Only Microsoft's own, untouched tool is ever opened.
        $sig = $null
        try { $sig = Get-AuthenticodeSignature -LiteralPath $file } catch { }
        $signedByMicrosoft = $sig -and [string]$sig.Status -eq 'Valid' -and $sig.SignerCertificate -and ([string]$sig.SignerCertificate.Subject -match '(^|,\s*)O=Microsoft Corporation(,|$)')
        if (-not $signedByMicrosoft) {
            try { Remove-Item -LiteralPath $file -Force -ErrorAction Stop } catch { }
            $a = [DRDirect.MsgBox]::Show("The downloaded file was not signed by Microsoft, so it was deleted and NOT opened.`n`nNothing was changed. Open Microsoft's Windows 11 download page instead?", $title, 'YesNo', 'Warning')
            if ($a -eq 'Yes') { Open-DRWinUsbPage }
            return
        }
        try {
            Start-Process -FilePath $file -WorkingDirectory (Split-Path -Parent $file) | Out-Null
        } catch {
            [DRDirect.MsgBox]::Show("Microsoft's Media Creation Tool could not be opened: $($_.Exception.Message)`n`nNothing was changed.", $title, 'OK', 'Warning') | Out-Null
            return
        }
        [DRDirect.MsgBox]::Show("Microsoft's Media Creation Tool is opening (click Yes if Windows asks).`n`nIn it: accept the licence, choose USB flash drive, then pick your USB stick of 8 GB or more.`n`nEverything on that stick will be erased.", $title, 'OK', 'Information') | Out-Null
    })
    $script:DRWinUsbTimer.Start()
}
$ui.NavWinUsb.Add_Click({ Start-DRWindowsInstallUsb })

# ---------- Windows Update: check for and install Windows 10/11 updates ----------
# Uses Windows' own Windows Update service (the same one Settings uses), in its own window so every step shows.
# Only software updates; drivers are left to Windows' normal schedule. Nothing is sent anywhere by the Cleaner.
function Start-DRWindowsUpdate {
    $q = "Check for Windows updates and install them now?`n`n" +
        "Windows' own Windows Update does the work, in a separate window that shows each update. " +
        "Microsoft's licence terms for the updates are accepted, the same as Windows Update in Settings does.`n`n" +
        "You can keep using the PC. If an update needs a restart, the window says so - nothing restarts by itself."
    $a = [DRDirect.MsgBox]::Show($q, 'DRDirect PC Cleaner - Windows Update', 'YesNo', 'Question')
    if ($a -ne 'Yes') { return }
    $script = @'
$Host.UI.RawUI.WindowTitle = 'DRDirect PC Cleaner - Windows Update'
$clock = [Diagnostics.Stopwatch]::StartNew()
try {
    Write-Host ''
    Write-Host '  DRDirect PC Cleaner - Windows Update' -ForegroundColor Cyan
    Write-Host ''
    Write-Host '  Looking for Windows updates...' -ForegroundColor Yellow
    $session = New-Object -ComObject Microsoft.Update.Session
    $session.ClientApplicationID = 'DRDirect PC Cleaner'
    $found = $session.CreateUpdateSearcher().Search("IsInstalled=0 and IsHidden=0 and Type='Software'")
    if ($found.Updates.Count -eq 0) {
        Write-Host ''
        Write-Host '  Windows is up to date. Nothing to install.' -ForegroundColor Green
    } else {
        $list = New-Object -ComObject Microsoft.Update.UpdateColl
        foreach ($u in $found.Updates) { if (-not $u.EulaAccepted) { $u.AcceptEula() }; [void]$list.Add($u); Write-Host ('   - ' + $u.Title) }
        Write-Host ''
        Write-Host ('  Downloading {0} update(s)...' -f $list.Count) -ForegroundColor Yellow
        $dl = $session.CreateUpdateDownloader(); $dl.Updates = $list; [void]$dl.Download()
        $ready = New-Object -ComObject Microsoft.Update.UpdateColl
        foreach ($u in $list) { if ($u.IsDownloaded) { [void]$ready.Add($u) } }
        if ($ready.Count -eq 0) { throw 'The updates could not be downloaded. Check that the internet is on.' }
        Write-Host ('  Installing {0} update(s)...' -f $ready.Count) -ForegroundColor Yellow
        $inst = $session.CreateUpdateInstaller(); $inst.Updates = $ready
        $res = $inst.Install()
        Write-Host ''
        for ($k = 0; $k -lt $ready.Count; $k++) {
            $code = $res.GetUpdateResult($k).ResultCode
            $word = switch ($code) { 2 { 'Installed' } 3 { 'Installed (with warnings)' } 4 { 'FAILED' } 5 { 'Stopped' } default { 'Not done' } }
            $colour = if ($code -in 2, 3) { 'Green' } else { 'Red' }
            Write-Host ('   {0,-26} {1}' -f $word, $ready.Item($k).Title) -ForegroundColor $colour
        }
        Write-Host ''
        if ($res.RebootRequired) { Write-Host '  Restart the PC to finish installing the updates.' -ForegroundColor Cyan }
        else { Write-Host '  Done. No restart is needed.' -ForegroundColor Green }
    }
} catch {
    Write-Host ''
    Write-Host ('  Windows Update could not finish: ' + $_.Exception.Message) -ForegroundColor Red
    Write-Host '  Opening Windows Update in Settings instead.'
    try { Start-Process 'ms-settings:windowsupdate' } catch { }
}
$t = [TimeSpan]::FromSeconds([Math]::Round($clock.Elapsed.TotalSeconds))
Write-Host ''
Write-Host ('  Time taken: {0} min {1} sec' -f [int][Math]::Floor($t.TotalMinutes), $t.Seconds)
Write-Host ''
Read-Host '  Press Enter to close this window'
'@
    try {
        $encoded = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($script))
        # Installing Windows updates needs administrator rights; Windows asks if the Cleaner does not have them.
        Start-Process -FilePath 'powershell.exe' -Verb RunAs -ArgumentList '-NoProfile', '-ExecutionPolicy', 'Bypass', '-EncodedCommand', $encoded | Out-Null
    } catch {
        [DRDirect.MsgBox]::Show("Windows Update could not be started: $($_.Exception.Message)`n`nOpening Windows Update in Settings instead.", 'DRDirect PC Cleaner - Windows Update', 'OK', 'Warning') | Out-Null
        try { Start-Process 'ms-settings:windowsupdate' } catch { }
    }
}
